css:
/* Oma's Mahjong — all styles.
   1 base · 2 buttons & chips · 3 home · 4 menu screens · 5 game screen · 6 tiles · 7 tray & tools
   8 pop-ups · 9 celebrations · 10 leaderboard & family · 11 tasks, stats, special tiles
   12 themes (including Zonnebloem) · 13 small screens */

/* ========== 1 base ========== */
@font-face { font-family: Nunito; font-weight: 700; src: url(fonts/nunito-latin-700-normal.woff2) format('woff2'); }
@font-face { font-family: Nunito; font-weight: 800; src: url(fonts/nunito-latin-800-normal.woff2) format('woff2'); }
@font-face { font-family: Nunito; font-weight: 900; src: url(fonts/nunito-latin-900-normal.woff2) format('woff2'); }

:root {
  --ink: #3b2a14;
  --cream: #fff8e8;
  --cream2: #f6e9c8;
  --gold: #ffc531;
  --gold-d: #d99a00;
  --green: #2bb673;
  --green-d: #178a52;
  --orange: #ff8a3d;
  --orange-d: #d9621a;
  --blue: #3d9cf5;
  --blue-d: #1f6fc2;
  --pink: #ff6fa3;
  --pink-d: #d1477c;
  --muted: #8a7448;
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bot: env(safe-area-inset-bottom, 0px);
}
* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; user-select: none; -webkit-user-select: none; }
html, body { margin: 0; height: 100%; overflow: hidden; background: #0b4d3c; }
body { font-family: Nunito, 'Segoe UI', Roboto, Arial, sans-serif; font-weight: 800; color: var(--ink); touch-action: manipulation; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; padding: 0; }

#bg { position: fixed; inset: 0; transition: background .6s; }
#bg::after { /* soft vignette + subtle pattern so every background feels like a table */
  content: ''; position: absolute; inset: 0;
  background:
    radial-gradient(circle at 50% 35%, transparent 40%, rgba(0,0,0,.28) 100%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.035) 0 2px, transparent 2px 14px);
}
#app { position: fixed; inset: 0; padding-top: var(--safe-top); padding-bottom: var(--safe-bot); }
.screen { position: absolute; inset: var(--safe-top) 0 var(--safe-bot) 0; display: none; flex-direction: column; }
.screen.active { display: flex; animation: fadeIn .25s ease; }
@keyframes fadeIn { from { opacity: 0; } }
@keyframes pop { from { transform: scale(.6); opacity: 0; } }
@keyframes pulse { 50% { transform: scale(1.03); } }
@keyframes bob { 50% { translate: 0 -6px; } }
@keyframes spin { to { transform: rotate(360deg); } }

/* ========== 2 buttons & chips ========== */
.chip { background: rgba(0,0,0,.28); color: #fff; border-radius: 999px; padding: 6px 14px; font-weight: 900; font-size: 18px; white-space: nowrap; box-shadow: inset 0 -2px 0 rgba(0,0,0,.2); }
.big-chip { font-size: 22px; padding: 8px 18px; }
.icon-btn { width: 52px; height: 52px; border-radius: 16px; background: var(--cream); font-size: 26px; display: grid; place-items: center; box-shadow: 0 5px 0 var(--cream2), 0 7px 10px rgba(0,0,0,.25); color: var(--ink); flex: none; }
.icon-btn:active { transform: translateY(4px); box-shadow: 0 1px 0 var(--cream2); }
.icon-btn.small { width: 44px; height: 44px; font-size: 26px; border-radius: 14px; }

.big-btn { position: relative; display: flex; align-items: center; gap: 16px; width: 100%; padding: 16px 20px; border-radius: 24px; color: #fff; text-align: left; text-shadow: 0 2px 0 rgba(0,0,0,.18); transition: transform .08s; }
.big-btn b { display: block; font-size: 30px; font-weight: 900; line-height: 1.05; }
.big-btn small { display: block; font-size: 18px; font-weight: 800; opacity: .95; }
.big-btn .bb-icon { width: 58px; height: 58px; border-radius: 18px; background: rgba(255,255,255,.25); display: grid; place-items: center; font-size: 30px; flex: none; }
.big-btn:active { transform: translateY(5px); }
.big-btn.play { background: linear-gradient(#45d28a, var(--green)); box-shadow: 0 7px 0 var(--green-d), 0 10px 18px rgba(0,0,0,.3); }
.big-btn.play:active { box-shadow: 0 2px 0 var(--green-d); }
.big-btn.daily { background: linear-gradient(#ffa865, var(--orange)); box-shadow: 0 7px 0 var(--orange-d), 0 10px 18px rgba(0,0,0,.3); }
.big-btn.daily:active { box-shadow: 0 2px 0 var(--orange-d); }
.help-card { display: grid; grid-template-columns: 64px 1fr; gap: 4px 14px; align-items: center; }
.help-card .hico { font-size: 50px; grid-row: span 2; text-align: center; }
.help-card h3 { margin: 0; font-size: 26px; font-weight: 900; line-height: 1.1; }
.help-card p { margin: 0; font-size: 18px; font-weight: 800; color: var(--muted); line-height: 1.25; }
.help-card .stock { grid-column: 1 / -1; display: flex; align-items: center; gap: 8px; margin: 12px 0 2px; font-size: 18px; font-weight: 900; }
.help-card .stock i { width: 22px; height: 22px; border-radius: 50%; background: #e6d7b0; box-shadow: inset 0 2px 2px rgba(0,0,0,.15); }
.help-card .stock i.f { background: radial-gradient(circle at 35% 30%, #fff4b8 0 12%, #ffd84d 34%, #f2b01e 70%, #c98a00 100%); box-shadow: 0 2px 0 #a86f00; }
.help-card .stock span { margin-left: 4px; }
.help-card .once { grid-column: 1 / -1; justify-self: start; margin-top: 8px; padding: 5px 12px; border-radius: 999px; background: #fff0c2; box-shadow: inset 0 0 0 2px #f2cf6b; font-size: 17px; font-weight: 900; }
.help-card .big-btn { grid-column: 1 / -1; margin-top: 10px; justify-content: center; text-align: center; padding: 12px 16px; }
.help-card .big-btn b { font-size: 24px; }
.help-card .big-btn small { font-size: 16px; }
.big-btn.gold { background: linear-gradient(#ffd75e, var(--gold)); color: #5a3a00; text-shadow: none; box-shadow: 0 7px 0 var(--gold-d), 0 10px 18px rgba(0,0,0,.3); justify-content: center; text-align: center; }
.big-btn .streak { margin-left: auto; background: rgba(0,0,0,.18); border-radius: 999px; padding: 6px 12px; font-size: 20px; font-weight: 900; }
.big-btn.pulse { animation: pulse 1.6s ease-in-out infinite; }

.mid-btn { flex: 1; background: var(--cream); border-radius: 22px; padding: 14px 10px; font-size: 22px; font-weight: 900; display: flex; flex-direction: column; align-items: center; gap: 2px; box-shadow: 0 6px 0 var(--cream2), 0 9px 14px rgba(0,0,0,.25); }
.mid-btn > span { font-size: 34px; }
.mid-btn b { font-weight: inherit; }   /* translated labels (data-t) */
.mid-btn:active { transform: translateY(5px); box-shadow: 0 1px 0 var(--cream2); }
.mid-badge { position: absolute; top: -8px; right: -6px; background: var(--pink); color: #fff; font-style: normal; font-size: 14px; padding: 2px 8px; border-radius: 999px; box-shadow: 0 2px 0 var(--pink-d); }
.link-btn { display: block; margin: 16px auto 0; font-size: 20px; color: var(--muted); padding: 8px 16px; }
.reset-btn { display: block; margin: 14px auto 0; padding: 10px 16px; border-radius: 14px; font-size: 17px; color: #b3261e; background: #fbe3df; }

/* ========== 3 home ========== */
#home { padding: 14px 18px 18px; overflow: hidden; gap: clamp(6px, 1.2vh, 14px); }
#home > * { flex-shrink: 0; }
.home-top { display: flex; justify-content: space-between; align-items: center; }
.logo { text-align: center; margin: 2vh 0 2vh; flex: 1 0 auto; display: flex; flex-direction: column; align-items: center; justify-content: center; }
.logo h1 { margin: 10px 0 0; font-size: clamp(38px, 11vw, 56px); font-weight: 900; color: #fff; letter-spacing: -.5px; text-shadow: 0 4px 0 rgba(0,0,0,.25), 0 8px 20px rgba(0,0,0,.25); }
.greet { margin: 4px 0 0; color: #fff; font-size: 22px; opacity: .95; text-shadow: 0 2px 0 rgba(0,0,0,.2); }
.logo-tiles { display: flex; gap: 6px; height: 108px; align-items: flex-end; }
.lt { width: 66px; height: 86px; border-radius: 12px; background: linear-gradient(#fffef8, #f4ead2); box-shadow: 4px 5px 0 #d9caa0, 7px 9px 0 #1f7a5c, 8px 12px 14px rgba(0,0,0,.35); padding: 4px; animation: bob 3s ease-in-out infinite; }
.lt svg { width: 100%; height: 100%; display: block; }
.lt.t1 { transform: rotate(-9deg); }
.lt.t2 { margin-bottom: 18px; animation-delay: -1s; }
.lt.t3 { transform: rotate(9deg); animation-delay: -2s; }
.home-buttons { display: flex; flex-direction: column; gap: 18px; }
.row2 { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }   /* never wider than the screen */
.row2 .mid-btn { min-width: 0; }
.row2 .mid-btn b { min-width: 0; white-space: nowrap; }   /* a long word gets a smaller font instead (fitTexts) */
.row2 .mid-btn { position: relative; flex-direction: row; justify-content: center; gap: 8px; padding: 12px 8px; font-size: 19px; }
.row2 .mid-btn > span { font-size: 28px; }
.task-chip { font-size: 17px; padding: 6px 12px; letter-spacing: 1px; }
.task-chip.ready { background: linear-gradient(#ffd75e, var(--gold)); color: #5a3a00; animation: chipPulse 1.1s ease-in-out infinite; }
@keyframes chipPulse { 50% { transform: scale(1.12); box-shadow: 0 0 0 4px rgba(255,210,60,.5), 0 0 18px 6px rgba(255,200,0,.6); } }
/* the next goal under the menu (also on the win screen) */
.goal { margin-top: 16px; background: rgba(0,0,0,.25); color: #fff; border-radius: 18px; padding: 10px 14px; font-size: 17px; text-align: center; min-height: 20px; }
.goal:empty { display: none; }
.goal .bar { height: 10px; background: rgba(255,255,255,.25); border-radius: 9px; margin-top: 6px; overflow: hidden; }
.goal .bar i { display: block; height: 100%; background: linear-gradient(90deg, #ffe17a, var(--gold)); border-radius: 9px; }
.goal.sun { display: flex; gap: 10px; align-items: center; text-align: left; background: linear-gradient(135deg, #ffe066, #f7b733); color: #5a3a00; box-shadow: 0 4px 0 #c98a12, 0 8px 16px rgba(0,0,0,.25); }
.goal.sun .g-ico { font-size: 40px; animation: spin 8s linear infinite; }
.goal.sun > div { flex: 1; }
.goal.sun .bar { background: rgba(90,58,0,.18); }
.goal.sun .bar i { background: linear-gradient(90deg, #fff6c2, #fff); }

/* ========== 4 menu screens: levels, calendar, themes, prizes ========== */
.header { display: flex; align-items: center; gap: 12px; padding: 14px 16px; }
.header h2 { flex: 1; margin: 0; color: #fff; font-size: 30px; font-weight: 900; text-shadow: 0 3px 0 rgba(0,0,0,.25); }
.scroll { flex: 1; overflow-y: auto; padding: 4px 16px 28px; -webkit-overflow-scrolling: touch; }
.card { background: var(--cream); border-radius: 22px; padding: 16px; box-shadow: 0 6px 0 var(--cream2), 0 9px 16px rgba(0,0,0,.22); margin-bottom: 18px; }
h3.sec { color: #fff; font-size: 22px; margin: 6px 4px 10px; text-shadow: 0 2px 0 rgba(0,0,0,.25); }

/* levels */
.level-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px 10px; }
.lv { aspect-ratio: 1; border-radius: 22px; background: var(--cream); box-shadow: 0 6px 0 var(--cream2), 0 8px 12px rgba(0,0,0,.22); display: flex; flex-direction: column; align-items: center; justify-content: center; font-size: 28px; font-weight: 900; }
.lv small { font-size: 15px; letter-spacing: 1px; color: var(--gold-d); line-height: 1; margin-top: 2px; }
.lv small .off { color: #d8cdb0; }
.lv.current { background: linear-gradient(#45d28a, var(--green)); color: #fff; box-shadow: 0 6px 0 var(--green-d), 0 0 0 4px #fff, 0 8px 16px rgba(0,0,0,.3); animation: pulse 1.6s ease-in-out infinite; }
.lv.locked { background: rgba(20,30,25,.3); color: rgba(255,255,255,.7); box-shadow: none; font-size: 22px; }
.lv:active:not(.locked) { transform: translateY(4px); }
.lv.prize { position: relative; box-shadow: 0 6px 0 #c98a12, 0 0 0 4px #ffd23f, 0 8px 18px rgba(255,190,0,.6); }
.lv .prize-ico { position: absolute; top: -12px; right: -8px; font-size: 30px; animation: spin 8s linear infinite; }
.lv.lv-replay { position: relative; box-shadow: inset 0 0 0 3px #c95b3c, 0 6px 0 var(--cream2), 0 8px 12px rgba(0,0,0,.22); }
.lv .replay-mark { position: absolute; top: 7px; right: 9px; color: #a34125; font-size: 17px; }
.lv.prize .replay-mark { left: 9px; right: auto; }
#levelsFilter::before { width: calc((100% - 14px) / 2); }
#lvReplay:not(:empty) { margin-bottom: 18px; }
.levels-ready { text-align: center; font-size: 20px; font-weight: 800; }
#home .daily-shortcuts { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 10px; }
#home .daily-shortcuts #btnDaily { min-width: 0; padding-inline: 12px; }
#home .daily-shortcuts .bb-text { min-width: 0; width: 100%; }
#home .daily-top { display: flex; align-items: center; gap: 5px; justify-content: space-between; }
#home .daily-top b { font-size: clamp(18px, 6vw, 25px); }
#dailyHomeReward { padding: 5px 7px; border-radius: 11px; color: var(--ink); background: var(--cream); font-size: clamp(13px, 4vw, 16px); text-shadow: none; font-weight: 900; white-space: nowrap; }
#home #dailyLabel { display: flex; align-items: center; gap: 5px; font-weight: 800; }
.daily-face { display: inline-grid; place-items: center; width: 24px; height: 24px; background: var(--cream); border-radius: 50%; }
#home .daily-calendar { display: grid; gap: 3px; align-content: center; min-width: 70px; padding: 6px; font-size: 16px; }
@media (max-width: 391px), (orientation: landscape) and (max-height: 550px) {
  #home .daily-top { flex-wrap: wrap; gap: 3px 5px; }
  #home #dailyLabel { font-size: 15px; white-space: normal; }
  #home #dailyLabel .daily-face { flex: 0 0 24px; }
  #home #dailyLabel .daily-face:nth-of-type(3) { display: none; }
}

/* daily puzzle calendar */
.streak-card { display: flex; align-items: center; gap: 14px; }
.streak-card .flame { font-size: 48px; animation: bob 2s ease-in-out infinite; }
.streak-card b { font-size: 24px; display: block; }
.streak-card small { font-size: 17px; color: var(--muted); }
.cal-head { display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px; }
.cal-head b { font-size: 22px; text-transform: capitalize; }
.cal-days, .cal-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 6px; text-align: center; }
.cal-days span { font-size: 15px; color: #9b8758; }
.cal-grid { margin-top: 6px; }
.cd { aspect-ratio: 1; border-radius: 50%; display: grid; place-items: center; font-size: 19px; font-weight: 900; position: relative; }
.cd.future { color: #d6cbb0; }
.cd.done { background: radial-gradient(circle at 35% 30%, #ffe680, var(--gold) 60%, var(--gold-d)); color: #6a4500; box-shadow: 0 3px 0 #b07c00; }
.cd.done::after { content: '👑'; position: absolute; top: -9px; right: -5px; font-size: 14px; }
.cd.sel { outline: 4px solid var(--orange); outline-offset: 1px; }
.cd.today:not(.done) { background: #ffe9d6; }
.cal-count { text-align: center; margin-top: 12px; font-size: 18px; color: var(--muted); }

/* themes */
.theme-list { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; margin-bottom: 20px; }
.th { background: var(--cream); border-radius: 20px; padding: 12px 10px; box-shadow: 0 6px 0 var(--cream2), 0 8px 12px rgba(0,0,0,.2); text-align: center; font-size: 20px; font-weight: 900; position: relative; }
.th .pv { display: flex; justify-content: center; gap: 5px; margin-bottom: 8px; }
.th .pv .mini { width: 40px; height: 52px; border-radius: 8px; background: linear-gradient(#fffef8, #f1e6cb); box-shadow: 2px 3px 0 #d9caa0, 3px 5px 0 #1f7a5c; display: grid; place-items: center; padding: 2px; }
.th .pv .mini svg { width: 100%; height: 100%; }
.th .pv .mini .emo { font-size: 28px; }
.th.on, .bgc.on { box-shadow: 0 6px 0 var(--green-d), 0 0 0 5px var(--green), 0 8px 14px rgba(0,0,0,.25); }
.th.on::after, .bgc.on::after, .suncard.on::after { content: '✓'; position: absolute; top: -10px; right: -8px; width: 34px; height: 34px; border-radius: 50%; background: var(--green); color: #fff; display: grid; place-items: center; font-size: 22px; box-shadow: 0 2px 0 var(--green-d); }
.bg-list { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
.bgc { position: relative; height: 110px; border-radius: 20px; box-shadow: 0 6px 0 rgba(0,0,0,.2), 0 8px 12px rgba(0,0,0,.2); display: flex; align-items: flex-end; padding: 10px; color: #fff; font-size: 19px; text-shadow: 0 2px 3px rgba(0,0,0,.5); }
.bgc.locked { filter: grayscale(.85) brightness(.75); }
.bgc .lock { position: absolute; inset: 0; display: grid; place-items: center; font-size: 22px; text-align: center; line-height: 1.2; }
/* the Zonnebloem prize card */
.suncard { position: relative; width: 100%; display: grid; grid-template-columns: auto 1fr; gap: 6px 12px; align-items: center; text-align: left; padding: 14px; margin-bottom: 18px; border-radius: 22px;
  background: linear-gradient(135deg, #fff3a6 0%, #ffd23f 55%, #f2a516 100%); color: #5a3a00; box-shadow: 0 6px 0 #c98a12, 0 10px 18px rgba(0,0,0,.25); }
.suncard .sun-ico { font-size: 58px; grid-row: span 2; animation: spin 10s linear infinite; }
.suncard .sun-txt b { display: block; font-size: 26px; font-weight: 900; }
.suncard .sun-txt small { display: block; font-size: 16px; }
.suncard .bar { display: block; height: 10px; border-radius: 9px; background: rgba(90,58,0,.18); margin: 6px 0 2px; overflow: hidden; }
.suncard .bar i { display: block; height: 100%; background: #fff; border-radius: 9px; }
.suncard .sun-pv { grid-column: 2; display: flex; gap: 5px; }
.suncard .mini { width: 38px; height: 48px; border-radius: 8px; background: linear-gradient(#fffdf0, #fff0b8); box-shadow: 2px 3px 0 #e6c25a, 3px 5px 0 #5a9e3a; display: grid; place-items: center; }
.suncard .mini .emo { font-size: 26px; }
.suncard.locked { filter: saturate(.75); }
.suncard.locked .sun-pv { opacity: .55; }

/* prize cabinet */
.trophy-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }   /* equal columns: a long name gets a smaller font */
.trophy { min-width: 0; }
.trophy b, .trophy small { max-width: 100%; }
.trophy { background: rgba(20,30,25,.38); color: #fff; border-radius: 20px; padding: 12px 10px; text-align: center; display: flex; flex-direction: column; align-items: center; gap: 2px; }
.trophy .t-ico { font-size: 40px; filter: grayscale(1); opacity: .45; }
.trophy b { font-size: 17px; }
.trophy small { font-size: 14px; opacity: .9; line-height: 1.2; }
.trophy em { font-style: normal; font-size: 14px; opacity: .9; }
.trophy .bar { width: 80%; height: 8px; border-radius: 6px; background: rgba(0,0,0,.25); overflow: hidden; margin-top: 4px; }
.trophy .bar i { display: block; height: 100%; background: var(--gold); }
.trophy.got { background: var(--cream); color: var(--ink); box-shadow: 0 5px 0 var(--cream2), 0 8px 14px rgba(0,0,0,.22); }
.trophy.got .t-ico { filter: none; opacity: 1; animation: bob 3s ease-in-out infinite; }
.trophy.got em { color: var(--green-d); font-weight: 900; }
#trophies .trophy { padding: 8px; gap: 0; }
#trophies .trophy .t-ico { font-size: 27px; line-height: 30px; }
#trophies .trophy b { font-size: 20px; line-height: 24px; }
#trophies .trophy small { font-size: 15px; line-height: 18px; }
#trophies .trophy em { font-size: 15px; line-height: 17px; }
#trophies .trophy .bar { margin: 3px 0; }
#trophies .stat small { font-size: clamp(13px, 3.82vw, 15px); }

/* ========== 5 game screen ========== */
.topbar { display: flex; align-items: center; gap: 10px; padding: 10px 12px 6px; }
#game .topbar { padding: 6px 10px 4px; gap: 8px; }
#game .icon-btn { width: 44px; height: 44px; font-size: 22px; border-radius: 14px; box-shadow: 0 4px 0 var(--cream2), 0 6px 8px rgba(0,0,0,.22); }
#btnRestart, #game #btnRestart { font-size: 26px; font-weight: 900; }
.title-wrap { position: relative; flex: 1; color: #fff; text-align: center; }
#gameTitle { font-size: 19px; font-weight: 900; text-shadow: 0 2px 0 rgba(0,0,0,.25); }
.progress { height: 12px; border-radius: 9px; background: rgba(0,0,0,.28); margin-top: 4px; overflow: hidden; }
#progressBar.shine { animation: barShine 1s ease; }
@keyframes barShine { 30% { filter: brightness(1.5) saturate(1.3); box-shadow: 0 0 14px 4px rgba(255,220,80,.9); } }
/* the bar slides in from the left (transform: moved by the graphics chip, no layout on every frame) */
#progressBar { position: relative; height: 100%; width: 100%; border-radius: 0 9px 9px 0; background: linear-gradient(90deg, #ffe17a, var(--gold)); transform: translateX(-100%); transition: transform .4s cubic-bezier(.3,1.4,.6,1); box-shadow: inset 0 -2px 0 rgba(0,0,0,.12); }
#progressBar::before { content: ''; position: absolute; right: 100%; top: 0; bottom: 0; width: 40px; background: #ffe17a; box-shadow: inherit; }   /* (no gap when the bar springs a little too far) */
.chip.score { min-width: 60px; text-align: center; font-size: 17px; padding: 4px 10px; }
.chip.score { position: relative; isolation: isolate; }
.chip.score::after { content: ''; position: absolute; inset: 0; z-index: -1; border-radius: inherit; background: var(--gold); opacity: 0; }
/* (only size and see-through change: the graphics chip plays it without the game redrawing the top bar) */
.chip.score.bump { animation: scoreBump .35s ease; }
.chip.score.bump::after { animation: scoreGlow .35s ease; }
@keyframes scoreBump { 40% { transform: scale(1.25); } }
@keyframes scoreGlow { 40% { opacity: .85; } }
@keyframes bump { 40% { transform: scale(1.25); background: var(--gold); color: #5a3a00; } }
.board-reward .title-wrap { min-width: 0; height: 52px; display: grid; grid-template-rows: 21px 8px 19px; align-content: center; gap: 2px; }
.board-reward.oldbar .title-wrap { height: 44px; grid-template-rows: 18px 5px 17px; }
.board-reward #gameTitle { line-height: 21px; }
.board-reward .progress { height: 8px; margin-top: 0; }
.board-reward .chip.score { position: absolute; top: 6px; right: 70px; color: var(--ink); background: var(--cream); padding: 1px 8px; font-size: 15px; line-height: 19px; }
.board-reward.compact .chip.score { top: 2px; }
.board-reward .chip.score[hidden] { display: none; }
.flow-meter { display: flex; align-items: center; justify-content: center; gap: 5px; font-size: 15px; line-height: 1; color: var(--ink); }
.flow-meter .pips { display: inline-flex; align-items: center; gap: 3px; padding: 2px 5px; border-radius: 999px; background: var(--cream); }
.flow-meter .pip { width: 10px; height: 10px; border-radius: 50%; background: var(--cream2); }
.flow-meter .pip.on { background: var(--gold); box-shadow: inset 0 -2px var(--gold-d); }
.flow-name { font-weight: 900; color: var(--cream); text-shadow: 0 1px 2px var(--ink); white-space: nowrap; }
#flowReward { background: var(--cream); padding: 2px 6px; border-radius: 999px; white-space: nowrap; }
.title-wrap.msg-on > .flow-meter { opacity: 0; }
@media (max-width: 359px) {
  .board-reward .chip.score { right: 65px; min-width: 0; padding-inline: 5px; font-size: 13px; }
  .board-reward .title-wrap:has(+ .chip.score:not([hidden])) #gameTitle { padding-right: 20px; }
}
.grit-flower { display: grid; align-items: center; justify-content: center; grid-template-columns: 76px min(202px, 65%); gap: 12px; margin: 0 auto 12px; text-align: left; }
.grit-flower strong { display: block; font-size: 23px; line-height: 1.15; font-weight: 900; }
.grit-flower small { font-size: 16px; line-height: 1.25; }
.grit-petals { width: 76px; height: 76px; position: relative; }
.grit-petals i { position: absolute; top: 2px; left: 26px; width: 24px; height: 26px; border-radius: 52% 52% 38% 38%; transform-origin: 12px 36px; background: var(--cream2); }
.grit-petals i.on { background: var(--gold); box-shadow: inset 0 -2px var(--gold-d); }
.grit-petals span { position: absolute; top: 28px; left: 28px; width: 20px; height: 20px; border-radius: 50%; background: var(--gold-d); box-shadow: inset 0 -2px var(--ink); }
.auto-coin { position: fixed; left: 0; top: 0; z-index: 91; pointer-events: none; font-size: 36px; line-height: 1; filter: drop-shadow(0 2px 2px rgba(0,0,0,.3)); }
.win-stats .win-payout { color: var(--ink); background: var(--gold); }
.win-stats .win-payout b { font-size: 20px; white-space: nowrap; }
.win-cup-reached, .win-momentum { padding: 6px 8px; margin: 4px 0; border-radius: 12px; font-size: 17px; font-weight: 900; }
.win-cup-reached { color: var(--ink); background: #fff3c4; }
.win-momentum { color: var(--green-d); background: color-mix(in srgb, var(--green) 18%, #fff); }
.win-links { display: flex; align-items: center; justify-content: center; gap: 16px; }
.podium-icon { font-size: 39px; margin: 0 0 8px; line-height: 1.3; }
.modal-box .week-podium .fam-box { margin-bottom: 17px; }
.modal-box .week-podium .fr-name { font-size: 18px; }
.perfect-plaque { padding: 0 6px; }
.plaque-stars { font-size: 39px; margin-bottom: 8px; line-height: 1.3; }
.perfect-plaque .pf-hero { margin: 1px 0 20px; }
.pf-button { display: inline-grid; flex: none; place-items: center; padding: 0; background: none; }
.plaque-nudge { display: flex; flex-wrap: wrap; justify-content: center; align-items: center; gap: 6px; padding-top: 13px; border-top: 2px dashed var(--cream2); }
.passed-dialog .fam-box { margin: 12px 0 20px; }
.passed-dialog .btn-row .big-btn { flex: 1; min-width: 0; padding: 8px 6px; margin: 0; }
.passed-dialog .btn-row .big-btn b { font-size: 20px; }
.passed-dialog .passed-row { grid-template-columns: 36px minmax(0, 1fr) auto; gap: 10px; }
.passed-dialog .passed-row .fr-name { font-size: 20px; }
.passed-dialog .passed-row .fr-sub { font-size: 15px; }
.postcard-section { text-align: left; border-top: 2px solid var(--cream2); margin-top: 6px; padding-top: 7px; }
.postcard-section h3 { margin: 0 0 8px; font-size: 20px; }
.postcard-strip { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 6px; }
.postcard-strip .th { border: 2px solid var(--gold); border-radius: 12px; background: #fff3c4; padding: 3px 1px; min-width: 0; }
.postcard-strip .postcard-art { font-size: 22px; }
.postcard-strip .price { font-size: clamp(12px, 3.8vw, 16px); padding: 3px 4px; margin: 1px 0 2px; white-space: nowrap; }
.postcard-paper { position: relative; display: grid; justify-items: center; gap: 2px; margin: 10px 0; padding: 11px 14px; color: var(--ink); background: #fff3c4; border: 2px dashed #edc25a; border-radius: 18px; }
.postcard-paper .postcard-art { font-size: 48px; line-height: 1.2; }
.postcard-paper strong { font-size: 23px; }
.postcard-paper small, .postcard-paper q { font-size: 16px; }
.postcard-stamp { position: absolute; right: 10px; top: 10px; padding: 5px; border: 2px dotted var(--gold-d); border-radius: 5px; background: var(--cream); transform: rotate(6deg); }
.postcard-confirm .btn-row .big-btn { flex: 1; min-width: 0; margin-top: 0; padding: 8px; }
.postcard-confirm .btn-row .big-btn b, .postcard-confirm .btn-row .btn2 { font-size: 19px; }
.postcard-confirm .btn-row .btn2 { width: auto; flex: 0 0 auto; margin-top: 0; padding: 9px 12px; }
@media (max-height: 640px) {
  .win-cup-reached, .win-momentum { font-size: 15px; padding: 3px 4px; margin: 2px 0; }
  .win-stats .win-payout b { font-size: 17px; }
}

/* every finger goes straight to the game; the praise text stays above the tiles */
#boardWrap { flex: 1; position: relative; overflow: hidden; isolation: isolate; touch-action: none; -webkit-touch-callout: none; }
#board { position: absolute; inset: 0; --d: 5px; --fs: 30px; }

/* the message strip: praise and tips while playing, between the tray and the pile */
/* messages while playing: in the title spot of the top bar (title and progress step aside), never over the tiles */
#gameMsg { position: absolute; inset: -4px -2px; display: flex; align-items: center; justify-content: center; pointer-events: none; text-align: center; overflow: hidden; z-index: 4; }
.title-wrap > #gameTitle, .title-wrap > .progress { transition: opacity .25s; }
.title-wrap.msg-on > #gameTitle, .title-wrap.msg-on > .progress { opacity: 0; }
#gameMsg span { max-width: 100%; animation: msgIn .35s cubic-bezier(.3,1.6,.5,1); transition: opacity .35s, transform .35s; }
#gameMsg span.out { opacity: 0; transform: translateY(-8px); }
#gameMsg .msg { display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; background: rgba(25,18,5,.62); color: #fff; font-size: 14.5px; font-weight: 800; line-height: 1.15; padding: 3px 10px; border-radius: 12px; }
/* a "Wist je dat?" tip (specials.js tipEl): a cream card like the menu buttons with a small tile on the left showing what the tip is about;
   in the game right under the tray for 3 s, fading by itself, taps go through it; on the home screen under the greeting, always there */
.tip-box { display: flex; align-items: center; gap: 12px; text-align: left; text-shadow: none; line-height: 1.15; color: var(--ink); position: relative; background: var(--cream); border-radius: 14px; padding: 6px 14px 6px 8px; border: 1px solid var(--cream2); box-shadow: 0 2px 8px rgba(0,0,0,.18); }
.tip-box::before { content: ""; position: absolute; left: 22px; bottom: -6px; width: 10px; height: 10px; background: var(--cream); border-right: 1px solid var(--cream2); border-bottom: 1px solid var(--cream2); transform: rotate(45deg); }
.tip-txt { display: flex; flex-direction: column; min-width: 0; }
.tip-txt b { font-size: 15px; font-weight: 900; }
.tip-tile { flex: none; width: 34px; height: 44px; margin-right: 4px; border-radius: 8px; background: linear-gradient(#fffef8, #f4ead2); box-shadow: 3px 3px 0 #d9caa0, 4px 5px 0 #1f7a5c, 4px 7px 8px rgba(0,0,0,.3); display: grid; place-items: center; font-style: normal; font-size: 22px; }
#home .home-tip { max-width: 96%; margin-top: 8px; }
#home .home-tip[hidden] { display: none; }
#gameMsg .big { font-size: 23px; font-weight: 900; color: #fff; line-height: 1; white-space: nowrap; -webkit-text-stroke: 1px rgba(120,60,0,.35); text-shadow: 0 3px 0 #e08a00, 0 6px 14px rgba(0,0,0,.35); }
@keyframes msgIn { from { opacity: 0; transform: scale(.4); } to { opacity: 1; transform: scale(1); } }
.float { position: fixed; z-index: 60; pointer-events: none; color: #fff; font-weight: 900; font-size: 26px; text-shadow: 0 2px 0 #c77700, 0 4px 8px rgba(0,0,0,.4); animation: floatUp .9s ease-out forwards; }
.float.sc { font-size: 22px; animation: floatSc .9s ease-out forwards; }
@keyframes floatSc { from { transform: translate(-50%, 18px) scale(1.4); opacity: 0; } 25% { opacity: 1; transform: translate(-50%, 6px) scale(1.15); } to { transform: translate(-50%, -14px) scale(.7); opacity: 0; } }
@keyframes floatUp { from { transform: translate(-50%, 0) scale(.7); opacity: 1; } 30% { transform: translate(-50%, -20px) scale(1.2); } to { transform: translate(-50%, -70px) scale(1); opacity: 0; } }
#fx { position: fixed; inset: 0; width: 100%; height: 100%; pointer-events: none; z-index: 70; }
#fxl { position: fixed; inset: 0; pointer-events: none; z-index: 70; overflow: hidden; contain: strict; }   /* sparkles and emoji (fx.js) */
.fxp { position: absolute; display: block; will-change: transform, opacity; }
.fxp.dot { border-radius: 50%; }
.fxp.emo { line-height: 1; text-align: center; font-family: 'Noto Color Emoji', 'Apple Color Emoji', 'Segoe UI Emoji', sans-serif; }
#toast { position: fixed; left: 50%; bottom: calc(120px + var(--safe-bot)); transform: translate(-50%, 30px); background: rgba(30,20,5,.88); color: #fff; padding: 12px 20px; border-radius: 18px; font-size: 19px; opacity: 0; transition: all .3s; z-index: 80; width: max-content; max-width: min(88vw, 420px); text-align: center; pointer-events: none; }
#toast.on { opacity: 1; transform: translate(-50%, 0); }
#toast.top { bottom: auto; top: calc(10px + var(--safe-top)); transform: translate(-50%, -30px); }
#toast.top.on { transform: translate(-50%, 0); }

/* a stuck tile: arrows to the tiles in the way */
.blk-arrow { position: absolute; z-index: 2000000; pointer-events: none; transform: translate(-50%, -50%) rotate(var(--a)); animation: blkNudge 1.3s ease-in-out forwards; filter: drop-shadow(0 2px 3px rgba(0,0,0,.45)); }
.blk-arrow svg { width: 100%; height: 100%; display: block; }
@keyframes blkNudge {
  0% { opacity: 0; transform: translate(-50%, -50%) rotate(var(--a)) translateX(-40%) scale(.6); }
  15% { opacity: 1; transform: translate(-50%, -50%) rotate(var(--a)) translateX(0) scale(1); }
  30% { transform: translate(-50%, -50%) rotate(var(--a)) translateX(22%); }
  45% { transform: translate(-50%, -50%) rotate(var(--a)) translateX(0); }
  60% { transform: translate(-50%, -50%) rotate(var(--a)) translateX(22%); }
  80% { opacity: 1; transform: translate(-50%, -50%) rotate(var(--a)) translateX(0); }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(var(--a)) translateX(0); }
}

/* ========== 6 tiles ========== */
.tile { position: absolute; border-radius: 14%; background: var(--tile-face, linear-gradient(160deg, #fffef9 0%, #fbf4e2 55%, #efe2c0 100%));
  box-shadow: calc(var(--d) * .5) calc(var(--d) * .6) 0 0 var(--tile-rim, #e1d2a8), var(--d) calc(var(--d) * 1.2) 0 0 var(--tile-lip, #27906d), calc(var(--d) * 1.1) calc(var(--d) * 1.5) calc(var(--d) * 1.2) 0 rgba(0,0,0,.35);
  transition: transform .14s ease, opacity .25s ease; cursor: pointer; }
.tile .face { position: absolute; inset: 5% 6%; display: grid; place-items: center; pointer-events: none; }
.tile .face svg, .tile .face .fi { width: 100%; height: 100%; display: block; }
.fi { pointer-events: none; background: center / contain no-repeat; }
.tile .emo { font-size: var(--fs); line-height: 1; font-family: 'Noto Color Emoji', 'Apple Color Emoji', 'Segoe UI Emoji', sans-serif; }
.tile::after { content: ''; position: absolute; inset: 0; border-radius: inherit; background: rgba(60,40,10,.30); opacity: 0; transition: opacity .25s; pointer-events: none; }
#board.hl .tile.blocked::after { opacity: 1; }
.tile.hint::before { content: ''; position: absolute; inset: -4px; border-radius: 16%; border: 4px solid #4fc3ff; box-shadow: 0 0 18px 6px rgba(80,200,255,.8); animation: hintGlow .7s ease-in-out infinite alternate; pointer-events: none; }
@keyframes hintGlow { to { box-shadow: 0 0 6px 2px rgba(80,200,255,.5); } }
.tile.shake { animation: shake .3s; }
@keyframes shake { 20%, 60% { translate: -5px 0; } 40%, 80% { translate: 5px 0; } }
.tile.hidden { display: none; }
.tile.returning { visibility: hidden; }   /* put back from the tray: shown when its flying copy lands */
.tile.flip { animation: flip .45s ease; }
@keyframes flip { 0% { transform: scale(1); } 45% { transform: scale(.2) rotate(15deg); opacity: .4; } 100% { transform: scale(1); } }
.lyr { position: absolute; inset: 0; pointer-events: none; }   /* the tiles of one layer of the pile (renderBoard) */
.lyr > .tile { pointer-events: auto; }
.lyr.enter { animation: lyrEnter .55s backwards cubic-bezier(.3,1.45,.6,1); }
@keyframes lyrEnter { from { transform: translateY(-46px) scale(.94); opacity: 0; } }
.tile.flying { position: fixed; z-index: 90; transform-origin: 0 0; pointer-events: none; margin: 0; }
.popout { animation: popout .23s ease forwards !important; }
@keyframes popout { to { transform: scale(1.35); opacity: 0; } }
.tile.flying.popout { animation: none !important; opacity: 0; transition: opacity .2s !important; }
#board .tile.blocker { animation: blockerPulse 1.3s ease-in-out; }
#board .tile.blocker::after { opacity: 0 !important; }
@keyframes blockerPulse {
  0%, 100% { box-shadow: calc(var(--d) * .5) calc(var(--d) * .6) 0 0 #e1d2a8, var(--d) calc(var(--d) * 1.2) 0 0 #27906d; }
  25%, 65% { box-shadow: 0 0 0 4px #ff8a00, 0 0 16px 5px rgba(255,140,0,.75); }
  45% { box-shadow: 0 0 0 2px #ff8a00, 0 0 6px 2px rgba(255,140,0,.5); }
}
/* face-down tiles */
.tile.back { background:
    radial-gradient(circle at 50% 50%, #ffe08a 0 9%, #e8b13a 10% 14%, transparent 15%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px),
    repeating-linear-gradient(-45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px),
    linear-gradient(160deg, #3dbb90, #1b8063); }
.tile.back .face { visibility: hidden; }
.tile.back::after { background: rgba(10,30,20,.35); }
/* corner numbers can be switched off in the settings */
body.nonum .cn { display: none; }

/* ========== 7 tray & tools ========== */
.traybar { display: flex; justify-content: center; padding: 0 12px 4px; }
/* a pile limited by the height of the screen (board.js fitGeo): a little less padding around the top bar and the tray, nothing smaller */
#game.compact .topbar { padding: 2px 10px 1px; }
#game.compact .traybar { padding-bottom: 0; }
#game.compact #tray { padding: 3px 6px; }
#tray { --slotw: min(12.5vw, 60px, 7vh); display: grid; grid-template-columns: repeat(4, var(--slotw)); gap: 6px; padding: 6px; border-radius: 16px;
  background: var(--tray-bg, linear-gradient(#8a5a33, #6b4224)); box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 4px 0 var(--tray-lip, #4a2d17), 0 8px 14px rgba(0,0,0,.3); transition: box-shadow .3s; --sfs: 30px; }
#tray .slot { aspect-ratio: 1 / 1.24; border-radius: 10px; background: var(--tray-well, rgba(0,0,0,.28)); box-shadow: inset 0 3px 5px rgba(0,0,0,.45); position: relative; }
#tray.warn { box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 4px 0 var(--tray-lip, #4a2d17), 0 0 0 4px #ffb300, 0 8px 18px rgba(255,170,0,.55); }
#tray.full { box-shadow: inset 0 3px 6px rgba(0,0,0,.45), 0 4px 0 var(--tray-lip, #4a2d17), 0 0 0 4px #ff4d4d, 0 8px 22px rgba(255,60,60,.6); animation: trayPulse 1s ease-in-out infinite; }
@keyframes trayPulse { 50% { transform: scale(1.02); } }
.tmini { position: absolute; inset: 0; border-radius: 10px; background: var(--tile-face, linear-gradient(160deg, #fffef9, #efe2c0)); box-shadow: 2px 2px 0 var(--tile-rim, #d9caa0), 2px 4px 0 var(--tile-lip, #27906d); display: grid; place-items: center; padding: 3px; }
.tmini svg, .tmini .fi { width: 100%; height: 100%; display: block; }
.tmini .emo { font-size: var(--sfs); line-height: 1; }
.tmini.land { animation: land .25s ease; }
@keyframes land { 0% { transform: scale(1.15); } 100% { transform: scale(1); } }
.tmini.arriving { visibility: hidden; }
.tmini.ghost { position: fixed; inset: auto; z-index: 89; pointer-events: none; }

/* the helpers (Spieken, Steen terugleggen) sit left and right of the tray, in the tray's row: they take no height from the pile.
   Cream cards like home and restart (58 x 56 px, the name under the icon, the gold stock number on the corner). The card's 5 px
   edge ends exactly on the tray's bottom line and its centre is under home / restart; a press sinks 4 px like theirs. */
.traybar { position: relative; }
.toolbar { position: absolute; inset: 0 7px 1px; display: flex; justify-content: space-between; align-items: flex-end; pointer-events: none; }
#game .toolbar { bottom: 5px; }   /* the traybar has 4 px padding: the card edge (5 px) ends on the tray's bottom line */
#game.compact .toolbar { bottom: 1px; }   /* compact mode has no padding (it used to pin the row to 0) */
.tool { pointer-events: auto; position: relative; width: 58px; height: var(--toolh, 56px); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px; padding: 0;
  border-radius: 17px; background: var(--cream); color: var(--ink); box-shadow: 0 5px 0 var(--cream2), 0 7px 10px rgba(0,0,0,.25); transition: transform .12s; }
.tool.gone { display: none; }
.tool > span { font-size: 25px; line-height: 1; }
.tool > b { display: block; font-size: 12px; font-weight: 900; line-height: 1; }
.tool .cnt { display: grid; place-items: center; position: absolute; top: -3px; right: -8px; min-width: 22px; height: 22px; padding: 0 5px; border-radius: 999px; font-size: 14px; font-weight: 900; font-style: normal; color: var(--ink);
  background: radial-gradient(circle at 35% 30%, #fff4b8 0 12%, #ffd84d 34%, #f2b01e 70%, #c98a00 100%); box-shadow: 0 2px 0 #a86f00; }
.tool:active, .tool.pressed { transform: translateY(4px); box-shadow: 0 1px 0 var(--cream2), 0 2px 4px rgba(0,0,0,.25); }
.tool.used > span { opacity: .35; filter: grayscale(1); }
.tool.count > span { font-size: 26px; font-weight: 900; color: #6a4300; }   /* Spieken's countdown 4...1 in place of the icon */
.tool.count .cnt { display: none; }
/* waiting for the tile tap (Terug) or counting down (Spieken): the game's armed look. It grows 6 % only, so the card and its ring stay
   clear of home above it; the top bar sits above this row so the soft glow goes behind home */
.toolbar.nogrow .tool.armed { transform: none; }   /* (tight phones: ring and glow only, board.js fitToolbar) */
.tool.armed { transform: scale(1.06); animation: helperArmed 1s ease-in-out infinite; }
@keyframes helperArmed {
  0%, 100% { box-shadow: 0 5px 0 var(--cream2), 0 0 0 3px #fff3c4, 0 0 14px 6px rgba(255,200,40,.75); }
  50% { box-shadow: 0 5px 0 var(--cream2), 0 0 0 3px #ffe27a, 0 0 18px 8px rgba(255,200,40,.9); } }
@media (prefers-reduced-motion: reduce) { .tool.armed { animation: none; box-shadow: 0 5px 0 var(--cream2), 0 0 0 3px #fff3c4, 0 0 18px 8px rgba(255,200,40,.85); } }
#game .topbar { position: relative; z-index: 3; }
#game .topbar .icon-btn { width: 52px; height: 52px; font-size: 26px; border-radius: 16px; }
#game.oldbar .topbar .icon-btn { width: 44px; height: 44px; font-size: 22px; border-radius: 14px; }   /* board.js begin(): measures the pile's shape as before the bigger buttons */
#board .tile.peeked { outline: 4px solid #ffc531; outline-offset: -2px; border-radius: 10px; }   /* Spieken: a face-down tile shown for 4 s */
#tray .tmini.pulse { animation: trayPulse .8s ease-in-out infinite; }   /* Steen terugleggen: tap one of these */
@keyframes trayPulse { 0%, 100% { transform: scale(1); filter: none; } 50% { transform: scale(1.12); filter: drop-shadow(0 0 6px #ffc531) brightness(1.1); } }
@media (prefers-reduced-motion: reduce) { #tray .tmini.pulse { animation: none; outline: 3px solid #ffc531; } }

/* ========== 8 pop-ups ========== */
#modal { position: fixed; inset: 0; background: rgba(10,20,15,.6); display: grid; place-items: center; z-index: 65; padding: 20px; }
#modal.hidden { display: none; }
.modal-box { width: 100%; max-width: 420px; background: var(--cream); border-radius: 28px; padding: 24px 20px 20px; text-align: center; box-shadow: 0 8px 0 var(--cream2), 0 20px 40px rgba(0,0,0,.4); animation: pop .4s cubic-bezier(.3,1.5,.6,1); max-height: 92vh; overflow-y: auto; }
.modal-box h2 { margin: 0 0 6px; font-size: 32px; font-weight: 900; }
.modal-box p { font-size: 20px; margin: 8px 0 16px; line-height: 1.35; }
.modal-box .big-btn { justify-content: center; text-align: center; margin-top: 10px; }
.modal-box .big-btn b { font-size: 26px; }
.modal-box .note { font-size: 17px; color: var(--muted); }
.modal-box .note.small { font-size: 16px; }
/* settings */
.set-row { display: flex; justify-content: space-between; align-items: center; padding: 14px 4px; border-bottom: 2px dashed #eadcb6; font-size: 21px; text-align: left; }
.set-row:last-of-type { border-bottom: 0; }
/* language choice: two buttons side by side */
.lang-pick { display: flex; gap: 6px; }
.lang-pick .lp { font: inherit; font-size: 16px; font-weight: 800; padding: 7px 11px; border-radius: 12px; border: 2px solid #d9c38f; background: #fff8e6; color: var(--ink); cursor: pointer; }
.lang-pick .lp.on { background: var(--green, #2fa36b); border-color: transparent; color: #fff; }
.tog { width: 72px; height: 40px; border-radius: 999px; background: #d8ccb0; position: relative; transition: background .2s; flex: none; }
.tog::after { content: ''; position: absolute; top: 4px; left: 4px; width: 32px; height: 32px; border-radius: 50%; background: #fff; box-shadow: 0 2px 4px rgba(0,0,0,.3); transition: left .2s; }
.tog.on { background: var(--green); }
.tog.on::after { left: 36px; }
.version { margin-top: 10px; font-size: 14px; color: #9b8758; }
/* how to play: a little tray with tiles */
.how-tray { display: grid; grid-template-columns: repeat(4, 52px); gap: 6px; justify-content: center; padding: 8px; margin: 6px auto 10px; width: max-content; border-radius: 16px; background: linear-gradient(#8a5a33, #6b4224); }
.how-tray .hm { height: 66px; border-radius: 9px; background: linear-gradient(#fffef8, #f1e6cb); padding: 3px; }
.how-tray .hm svg { width: 100%; height: 100%; }
.how-tray .hm .emo { display: grid; place-items: center; height: 100%; font-size: 40px; line-height: 1; }
body.sunny .how-tray { background: linear-gradient(#f3b73a, #c98317); }
body.sunny .how-tray .hm { background: linear-gradient(#fffef4, #f9e39a); }
.how-tray .hm.empty { background: rgba(0,0,0,.28); }
.how-tray .hm.glow { outline: 4px solid #ffb300; outline-offset: 1px; }
.backmini { background:
    radial-gradient(circle at 50% 50%, #ffe08a 0 9%, #e8b13a 10% 14%, transparent 15%),
    repeating-linear-gradient(45deg, rgba(255,255,255,.13) 0 2px, transparent 2px 8px),
    linear-gradient(160deg, #3dbb90, #1b8063) !important; }
.unlock-pv { height: 120px; border-radius: 20px; margin: 10px 0; box-shadow: inset 0 0 0 4px rgba(255,255,255,.6); }
/* name and avatar */
.name-in { width: 100%; font: inherit; font-size: 22px; padding: 12px 14px; border-radius: 14px; border: 3px solid #e6d6ac; background: #fff; color: var(--ink); text-align: center; user-select: text; -webkit-user-select: text; }
.name-in:focus { outline: none; border-color: var(--gold); }
.quick-names { display: flex; gap: 8px; justify-content: center; align-items: center; margin: 10px 0; flex-wrap: nowrap; }   /* one row in every language (fitTexts: .fit-row) */
.qn { background: #efe2c0; border-radius: 999px; padding: .35em .8em; font-size: 1em; white-space: nowrap; flex: 0 1 auto; }
.quick-names { font-size: 17px; }
.avatars { display: grid; grid-template-columns: repeat(6, 1fr); gap: 6px; margin: 4px 0 6px; }
.av { font-size: 28px; border-radius: 12px; padding: 4px 0; background: #fff; }
.av.on { background: #ffe58a; box-shadow: 0 0 0 3px var(--gold); }
.fr-title { margin: 12px 0 6px; font-size: 19px; }
.frames { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; margin-bottom: 8px; }
.frm { background: #fff; border-radius: 14px; padding: 10px 2px 6px; display: grid; justify-items: center; gap: 6px; }
.frm .ra { width: 44px; height: 44px; font-size: 26px; }
.frm small { font-size: 11px; line-height: 1.15; color: #6a5530; font-weight: 800; }
.frm.on { background: #ffe58a; box-shadow: 0 0 0 3px var(--gold); }
.frm.locked { opacity: .5; }
.frm.locked .ra { filter: grayscale(1); }

/* ========== 9 celebrations ========== */
.stars { display: flex; justify-content: center; gap: 6px; margin: 10px 0 8px; height: 84px; align-items: flex-end; }
.stars .st { font-size: 64px; color: #e2d6b5; line-height: 1; transform: scale(.5); opacity: .5; transition: all .4s cubic-bezier(.3,1.8,.5,1); }
.stars .st:nth-child(2) { font-size: 80px; }
.stars .st.on { color: var(--gold); transform: scale(1); opacity: 1; text-shadow: 0 4px 0 var(--gold-d), 0 0 22px rgba(255,200,0,.8); }
.win-stats { display: flex; justify-content: center; gap: 12px; margin: 8px 0 6px; }
.win-stats div { background: #fff; border-radius: 16px; padding: 8px 14px; font-size: 16px; color: var(--muted); min-width: 96px; }
.win-stats b { display: block; font-size: 26px; color: var(--ink); }
.perfect { height: 0; overflow: visible; font-size: 30px; font-weight: 900; color: #ff8a00; text-shadow: 0 3px 0 #ffd23f; opacity: 0; transform: scale(.3) rotate(-10deg); transition: all .45s cubic-bezier(.3,1.8,.5,1); }
.perfect.on { height: 40px; opacity: 1; transform: scale(1) rotate(-4deg); }
.chase { font-size: 17px !important; margin: 6px 0 4px !important; color: #5c4520; }
.sun-big { font-size: 96px; line-height: 1; animation: sunPop 1.2s cubic-bezier(.3,1.6,.5,1), spin 9s linear 1.2s infinite; }
@keyframes sunPop { 0% { transform: scale(.1) rotate(-180deg); } 100% { transform: scale(1) rotate(0); } }
.tools-new { display: flex; justify-content: center; gap: 18px; font-size: 64px; margin: 6px 0; }
.tools-new span { animation: sunPop 1s cubic-bezier(.3,1.6,.5,1) backwards; }
.tools-new span:nth-child(2) { animation-delay: .2s; }
.tools-new.off span { filter: grayscale(1); opacity: .45; }   /* not earned (from level 50) */
.tr-new { display: grid; gap: 10px; margin: 12px 0; }
.trn { display: flex; align-items: center; gap: 12px; background: #fff; border-radius: 16px; padding: 10px 12px; text-align: left; animation: pop .5s cubic-bezier(.3,1.5,.6,1) backwards; }
.trn:nth-child(2) { animation-delay: .15s; } .trn:nth-child(3) { animation-delay: .3s; } .trn:nth-child(4) { animation-delay: .45s; }
.trn span { font-size: 40px; }
.trn b { display: block; font-size: 20px; }
.trn small { font-size: 15px; color: var(--muted); }
#flash { position: fixed; inset: 0; pointer-events: none; z-index: 75; opacity: 0;
  background: radial-gradient(circle at 50% 45%, rgba(255,255,255,.85) 0%, rgba(255,230,120,.5) 25%, rgba(255,120,200,.3) 45%, rgba(120,200,255,.2) 65%, transparent 80%); }
#flash.on { animation: flash .7s ease-out; }
@keyframes flash { 0% { opacity: 0; } 15% { opacity: 1; } 100% { opacity: 0; } }
.bee { position: fixed; left: -60px; z-index: 76; font-size: 40px; pointer-events: none; animation: beefly 2.6s ease-in-out forwards; }
@keyframes beefly {
  0% { transform: translate(0, 0) scaleX(-1); }
  25% { transform: translate(30vw, -40px) scaleX(-1); }
  50% { transform: translate(55vw, 30px) scaleX(-1); }
  75% { transform: translate(80vw, -30px) scaleX(-1); }
  100% { transform: translate(115vw, 10px) scaleX(-1); }
}
/* hearts */
.heart-big { font-size: 110px; line-height: 1; margin: 0 0 4px; animation: heartBeat 1s ease-in-out infinite; filter: drop-shadow(0 6px 10px rgba(232,87,140,.45)); }
@keyframes heartBeat { 0%, 100% { transform: scale(1); } 15% { transform: scale(1.18); } 30% { transform: scale(1); } 45% { transform: scale(1.12); } }
.heart-h { color: #c2306b; }
.heart-who { font-size: 23px !important; }
#heartPop { position: fixed; inset: 0; z-index: 64; display: none; place-items: center; background: rgba(60,10,30,.35); }
#heartPop.on { display: grid; animation: fadeIn .25s ease; }
#heartPop .hp-card { background: var(--cream); color: var(--ink); border-radius: 26px; padding: 16px 26px 14px; text-align: center; display: grid; gap: 2px; border: 4px solid #ff7aa8; box-shadow: 0 8px 0 #e85d8f, 0 18px 40px rgba(0,0,0,.4); animation: pop .45s cubic-bezier(.3,1.6,.5,1); max-width: 86vw; }
#heartPop .hp-heart { font-size: 96px; line-height: 1; animation: heartBeat 1s ease-in-out infinite; }
#heartPop b { font-size: 26px; color: #c2306b; }
#heartPop span { font-size: 21px; font-weight: 800; }
#heartPop small { font-size: 15px; color: var(--muted); margin-top: 6px; }

/* ========== 10 leaderboard & family ========== */
.name-chip { display: block; margin: 0 auto 14px; background: var(--cream); color: var(--ink); border-radius: 999px; padding: 8px 18px; font-size: 19px; font-weight: 900; box-shadow: 0 4px 0 var(--cream2), 0 6px 10px rgba(0,0,0,.2); }
.rk-tabs { display: flex; gap: 8px; justify-content: center; margin: 0 0 8px; }
.rk-tabs button { flex: 1; max-width: 180px; background: rgba(0,0,0,.25); color: #fff; border-radius: 999px; padding: 8px 10px; font-size: 17px; font-weight: 900; }
.rk-tabs button.on { background: var(--cream); color: var(--ink); box-shadow: 0 3px 0 var(--cream2); }
.wk-info { text-align: center; color: #fff; font-size: 15px; font-weight: 700; margin: 0 0 10px; text-shadow: 0 1px 2px rgba(0,0,0,.4); line-height: 1.35; }
.wk-info b { color: #ffe27a; }
.rank-list { display: grid; gap: 8px; }
.rrow { display: grid; grid-template-columns: 46px 40px 1fr auto; align-items: center; gap: 6px; background: var(--cream); color: var(--ink); border-radius: 16px; padding: 6px 12px; height: 52px; box-shadow: 0 3px 0 var(--cream2); }
.rrow .rk { font-size: 20px; font-weight: 900; text-align: center; color: var(--muted); }
.rrow .rn { font-size: 18px; font-weight: 900; line-height: 1.1; overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.rrow .rn i { font-style: normal; font-weight: 700; font-size: 14px; color: var(--muted); }
.rrow .rn small { display: block; font-size: 13px; color: #9b8758; font-weight: 700; }
.rrow .rp { font-size: 19px; font-weight: 900; font-variant-numeric: tabular-nums; }
.rrow.me { background: linear-gradient(135deg, #fff3a6, #ffd23f); box-shadow: 0 3px 0 #d99a00, 0 0 0 3px #ffb300; }
.rrow.fam { background: linear-gradient(135deg, #ffe9f1, #ffcfe1); box-shadow: 0 3px 0 #e85d8f, 0 0 0 3px #ff7aa8; }
.rrow .fam-tag { font-style: normal; font-size: 16px; font-weight: 900; vertical-align: 0; }
.rank-note { text-align: center; color: #fff; font-size: 15px; opacity: .9; margin-top: 14px; text-shadow: 0 1px 2px rgba(0,0,0,.4); }
.heart-btn { margin-left: 6px; font-size: 18px; background: #fff3c4; border-radius: 999px; padding: 2px 7px; vertical-align: middle; box-shadow: 0 2px 0 #e6c96a; }
.heart-btn.sent { background: #e9f7df; box-shadow: none; font-size: 14px; opacity: .8; }
/* avatars and the frames you can earn */
.ra { display: inline-grid; place-items: center; border-radius: 50%; }
.rrow .ra { position: relative; width: 38px; height: 38px; font-size: 24px; text-align: center; justify-self: center; }
.ra.small { width: 28px; height: 28px; font-size: 18px; vertical-align: middle; }
.ra.fr-bronze { box-shadow: 0 0 0 3px #c47a3a, inset 0 0 0 2px #f0b27a; background: #fbe7d3; }
.ra.fr-silver { box-shadow: 0 0 0 3px #a9b4c0, inset 0 0 0 2px #eef2f6; background: #f1f4f8; }
.ra.fr-gold { box-shadow: 0 0 0 3px #e0a800, 0 0 8px 2px rgba(255,200,0,.6), inset 0 0 0 2px #ffe680; background: #fff6cc; }
.ra.fr-sun { box-shadow: 0 0 0 3px #ffb300, 0 0 0 6px #6aa83a; background: #fff2a8; }
.ra.fr-heart { box-shadow: 0 0 0 3px #ff6f91, 0 0 8px 2px rgba(255,110,150,.5); background: #ffe3ea; }
.ra.fr-rainbow { background: #fff; box-shadow: 0 0 0 1.5px #ff5252, 0 0 0 3px #ffb300, 0 0 0 4.5px #4caf50, 0 0 0 6px #2196f3; }
.ra.fr-crown { background: #fff6cc; box-shadow: 0 0 0 3px #e0a800, 0 0 12px 3px rgba(255,200,0,.7); position: relative; }
/* the shop's photo frames (SHOP_CATALOG.frame borderCss / ringShadow) */
.ra.fr-frm_sky { background: #fff; border: 3.5px solid #3C9AD4; box-shadow: 0 0 0 4px #C2E7FF; }
.ra.fr-frm_tulip { background: #fff; border: 3.5px solid #E25B84; box-shadow: 0 0 0 4px #FFD1E1; }
.ra.fr-frm_delft { background: #fff; border: 3.5px solid #2763B5; box-shadow: 0 0 0 4px #CBE1FF; }
.ra.fr-frm_velvet { background: #fff; border: 3.5px solid #7D2846; box-shadow: 0 0 0 3px #F6D273, 0 0 0 5px #7D2846; }
.ra.fr-crown::before { content: '👑'; position: absolute; top: -.62em; font-size: .55em; }
/* the family box (leaderboard, win screen, climb) */
.fam-box { background: linear-gradient(135deg, #ffe9f1, #ffd6e6); border: 3px solid #ff7aa8; border-radius: 18px; padding: 8px 10px 6px; margin: 8px 0 12px; box-shadow: 0 4px 0 #e85d8f; color: var(--ink); text-align: left; }
.fam-fixed { padding: 0 16px; }
.fam-fixed .fam-box { margin: 2px 0 8px; }
.modal-box .fam-box { margin: 10px 0 6px; }
.fam-title { font-size: 17px; font-weight: 900; color: #b8336a; margin: 0 0 4px 4px; }
.fam-row { display: grid; grid-template-columns: 44px 36px 1fr auto; align-items: center; gap: 6px; padding: 5px 4px; border-radius: 12px; }
.fam-row.passed-row { grid-template-columns: 36px minmax(0, 1fr) auto; }
.fam-row + .fam-row { border-top: 2px dashed rgba(184,51,106,.25); }
.fam-row.me { background: rgba(255,255,255,.65); }
.fam-row .fr-rank { font-size: 20px; font-weight: 900; text-align: center; color: #8a3a5c; }
.fam-row .ra { position: relative; width: 34px; height: 34px; font-size: 22px; }
.fam-row .fr-name { font-size: 18px; font-weight: 900; line-height: 1.15; overflow: hidden; text-overflow: ellipsis; }
.modal-box .fam-row .fr-name { font-size: 16px; }
.fam-row .fr-name i { font-style: normal; font-size: 13px; color: var(--muted); }
.fam-row .fr-sub { display: block; font-size: 13.5px; font-weight: 800; color: #8a5a6e; }
.fam-row .fr-val { font-size: 17px; font-weight: 900; white-space: nowrap; font-variant-numeric: tabular-nums; }
.fam-row .hs { display: block; font-size: 12.5px; font-weight: 800; color: #b8336a; }
.fam-row .hs.seen { color: #2f8f3a; }
/* climbing past other players after a level */
.climb { position: relative; margin: 10px 0 6px; }
.climb .crow { position: absolute; left: 0; right: 0; transition: transform .45s cubic-bezier(.3,1.3,.5,1); }
.climb .crow.me { z-index: 2; }
.climb .crow.me.glow { animation: meGlow 1s ease-in-out 3; }
@keyframes meGlow { 50% { box-shadow: 0 3px 0 #d99a00, 0 0 0 4px #ffb300, 0 0 26px 8px rgba(255,200,0,.8); } }
.climb-msg { font-size: 19px; line-height: 1.35; min-height: 74px; }
.climb-msg small { font-size: 16px; color: var(--muted); }
.climb-up { display: inline-block; font-size: 30px; font-weight: 900; color: var(--green-d); animation: pop .5s cubic-bezier(.3,1.6,.5,1); }

/* the after-level screens (win + climb) are compact: everything fits without scrolling */
.modal-box.compact { padding: 16px 16px 12px; }
.compact h2 { font-size: 27px; line-height: 1.15; margin-bottom: 2px; }
.compact p { font-size: 16px; margin: 4px 0 6px; }
.compact .stars { height: 58px; margin: 2px 0 4px; }
.compact .stars .st { font-size: 46px; }
.compact .stars .st:nth-child(2) { font-size: 58px; }
.compact .win-stats { gap: 8px; margin: 4px 0; }
.compact .win-stats div { display: flex; align-items: baseline; gap: 6px; min-width: 0; padding: 4px 14px; font-size: 15px; }
.compact .win-stats b { display: inline; font-size: 22px; }
.compact .perfect { font-size: 24px; }
.win-stats .ws-streak { color: #c2410c; }
.win-stats .ws-streak b { color: #c2410c; }
.win-stats .ws-streak.bonus { background: #fff3c4; box-shadow: 0 0 0 3px #ffb300; animation: bump .6s ease 1.6s 2; }
.compact .win-stats { flex-wrap: wrap; }
.compact .win-stats div { padding: 4px 10px; }
.compact .perfect.on { height: 30px; }
.compact .chase { font-size: 15px !important; margin: 4px 0 !important; }
.compact .fam-box { margin: 6px 0; padding: 4px 8px; }
.compact .fam-title { font-size: 15px; margin-bottom: 0; }
.compact .fam-row { grid-template-columns: 34px 30px 1fr auto; padding: 2px 4px; }
.compact .fam-row .fr-rank { font-size: 17px; }
.compact .fam-row .ra { width: 28px; height: 28px; font-size: 18px; }
.compact .fam-row .fr-name { font-size: 16px; line-height: 1.1; }
.compact .fam-row .fr-sub { font-size: 12.5px; }
.compact .fam-row .fr-val { font-size: 16px; }
.compact .goal { background: #efe2c0; color: #5c4520; margin: 6px 0 2px; padding: 6px 10px; font-size: 15px; }
.compact .goal.sun .g-ico { font-size: 28px; }
.compact .goal .bar { height: 8px; margin-top: 4px; }
.compact .big-btn { padding: 11px 16px; margin-top: 8px; }
.compact .big-btn b { font-size: 24px; }
.compact .link-btn { margin-top: 2px; padding: 6px 16px; font-size: 18px; }
#wFamily { display: contents; }
.compact .win-family .fam-row { grid-template-columns: 27px 28px minmax(0, 1fr) minmax(78px, auto); gap: 4px; padding: 2px 1px; }
.compact .win-family .fr-name { white-space: nowrap; }
.compact .win-family .fr-val { display: flex; align-items: center; justify-content: flex-end; gap: 3px; }
.compact .win-family .points { min-width: 43px; text-align: right; }
.compact .win-family .heart-btn { display: inline-flex; align-items: center; justify-content: center; width: 32px; min-width: 32px; height: 28px; padding: 0; margin: 0; font-size: 19px; }
.compact .win-family .heart-btn.sent { font-size: 14px; }
.compact .win-family .fr-sub { white-space: normal; }
.presence-sub { white-space: nowrap; }
.presence-last { color: #775062; }
.presence-dot { position: absolute; right: -2px; bottom: 0; width: 10px; height: 10px; border-radius: 50%; background: #299d3b; box-shadow: 0 0 0 2px #ffdeeb; }
.presence-text { color: #237a2b; font-weight: 900; }
/* The heart picker uses the win popup's measured height; smaller viewports can scroll. */
.modal-box.heart-compose { height: var(--heart-dialog-height, auto); max-height: calc(100dvh - 40px); padding: 16px 16px 12px; display: flex; flex-direction: column; justify-content: space-between; gap: 4px; }
.heart-compose > * { flex-shrink: 0; }
.heart-compose .heart-big.sm { height: 32px; font-size: 32px; line-height: 1; margin: 0; }
.heart-compose h2 { font-size: 27px; line-height: 1.15; margin: 0; }
.heart-compose .note.small { font-size: 16px; line-height: 1.35; margin: 0; }
.heart-compose .msg-pick { gap: 6px; margin: 0; }
.heart-compose .msg-pick .mp { height: 38px; font-size: 17px; line-height: 1.2; padding: 5px 8px; border-width: 2px; border-radius: 14px; }
.custom-message { display: block; text-align: left; font-size: 16px; line-height: 1.2; font-weight: 900; color: var(--ink); margin: 0; }
.custom-message textarea { display: block; width: 100%; height: 56px; resize: none; margin: 4px 0 0; padding: 7px 10px; border: 2px solid #ff9bc4; border-radius: 14px; font: 700 17px/1.2 Nunito, system-ui, sans-serif; color: var(--ink); background: #fff9f5; }
.custom-message textarea::placeholder { color: #9b8758; }
.custom-message textarea:focus-visible { outline: 2px solid #e85d8f; outline-offset: 2px; }
.heart-compose .big-btn { margin: 0; padding: 11px 16px; }
.heart-compose .big-btn b { font-size: 24px; }
.heart-compose .link-btn { font-size: 18px; line-height: 1.1; margin: 0 auto; padding: 6px 16px; }
.heart-compose button:disabled { opacity: .65; cursor: wait; }
.heart-error { font-size: 14px; color: #ac2637; font-weight: 800; }
.modal-box.heart-confirm { height: auto; max-height: calc(100dvh - 40px); padding: 24px 16px 20px; display: flex; flex-direction: column; justify-content: flex-start; gap: 20px; }
.heart-confirm > * { flex-shrink: 0; }
.heart-confirm .heart-big { font-size: 80px; }
.heart-confirm .heart-big, .heart-compose .heart-big { align-self: center; width: max-content; }
.heart-confirm h2 { font-size: 27px; line-height: 1.15; margin: 0; }
.heart-confirm p { font-size: 20px; margin: 0; }
.heart-confirm .big-btn { padding: 11px 16px; }
.heart-confirm .big-btn b { font-size: 24px; }
.compact .climb { margin: 6px 0 4px; }
.compact .climb .rrow { height: 40px; padding: 2px 10px; grid-template-columns: 40px 32px 1fr auto; }
.compact .climb .rrow .ra { width: 30px; height: 30px; font-size: 19px; }
.compact .climb .rrow .rk { font-size: 17px; }
.compact .climb .rrow .rn { font-size: 16px; }
.compact .climb .rrow .rn small { font-size: 12px; }
.compact .climb .rrow .rp { font-size: 17px; }
@media (max-width: 392px) {
  .compact .climb .rrow { height: 44px; padding: 2px 6px; gap: 4px; grid-template-columns: 27px 32px minmax(0, 1fr) auto; }
  .compact .climb .rrow .rn { line-height: 1; }
  .compact .climb .rrow .rn small { white-space: normal; }
}
.compact .climb-msg { font-size: 16px; line-height: 1.3; min-height: 92px; }
.compact .climb-msg small { font-size: 14.5px; }
.compact .climb-up { font-size: 24px; }

/* ========== 11 tasks, stats, special tiles ========== */
.task-list { display: grid; gap: 10px; margin: 12px 0; text-align: left; }
.task { display: grid; grid-template-columns: 44px 1fr; gap: 10px; align-items: center; background: #fff; border-radius: 16px; padding: 10px 12px; box-shadow: 0 3px 0 var(--cream2); }
.task .t-ico { font-size: 30px; text-align: center; }
.task b { display: block; font-size: 18px; line-height: 1.2; }
.task small { font-size: 14px; color: var(--muted); font-weight: 700; }
.task .bar { display: block; height: 12px; background: #efe2c0; border-radius: 8px; margin: 6px 0 3px; overflow: hidden; }
.task .bar i { display: block; height: 100%; background: linear-gradient(90deg, #8be06a, #3fae2a); border-radius: 8px; transition: width .4s; }
.task.done { background: #e8f8dc; }
.chest-btn { display: flex; align-items: center; gap: 12px; width: 100%; text-align: left; background: #efe2c0; color: #6a5530; border-radius: 18px; padding: 10px 14px; font-size: 17px; font-weight: 800; margin-bottom: 8px; }
.chest-btn .chest-ico { font-size: 40px; filter: grayscale(.7); }
.chest-btn.ready { background: linear-gradient(#ffe27a, var(--gold)); color: #5a3a00; box-shadow: 0 5px 0 var(--gold-d); animation: chipPulse 1.1s ease-in-out infinite; }
.chest-btn.ready .chest-ico { filter: none; animation: wiggle .6s ease-in-out infinite; }
.chest-btn.opened { opacity: .75; }
.chest-btn.opened .chest-ico { filter: none; }
@keyframes wiggle { 25% { transform: rotate(-12deg) scale(1.1); } 75% { transform: rotate(12deg) scale(1.1); } }
.chest-open { font-size: 90px; line-height: 1; margin: 4px 0; }
.chest-open .lid { display: inline-block; animation: chestPop 1s cubic-bezier(.3,1.6,.5,1); }
@keyframes chestPop { 0% { transform: scale(.2) rotate(-30deg); } 40% { transform: scale(1.3) rotate(10deg); } 100% { transform: scale(1); } }
.chest-loot { display: flex; justify-content: center; gap: 14px; margin: 10px 0; }
.chest-loot div { background: #fff; border-radius: 16px; padding: 8px 18px; display: grid; justify-items: center; font-size: 30px; box-shadow: 0 3px 0 var(--cream2); animation: pop .5s .3s cubic-bezier(.3,1.6,.5,1) backwards; }
.chest-loot div + div { animation-delay: .5s; }
.chest-loot b { font-size: 26px; font-weight: 900; color: var(--green-d); }
.chest-loot small { font-size: 14px; color: var(--muted); font-weight: 700; }

.stats-card { background: var(--cream); color: var(--ink); border-radius: 20px; padding: 12px; margin-bottom: 14px; box-shadow: 0 4px 0 var(--cream2); }
.stats-card h3 { margin: 0 0 8px; font-size: 21px; text-align: center; }
.stats-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.stat { background: #fff; border-radius: 12px; padding: 6px 2px; display: grid; justify-items: center; text-align: center; }
.stat span { font-size: 22px; line-height: 1.1; }
.stat b { font-size: 18px; font-weight: 900; font-variant-numeric: tabular-nums; }
.stat small { font-size: 11.5px; color: var(--muted); font-weight: 700; line-height: 1.15; }

#board .tile.gold:not(.back) { background: linear-gradient(160deg, #fff8d0 0%, #ffe680 55%, #f2c230 100%); box-shadow: inset 0 0 0 2px #e0a800, 0 0 10px 2px rgba(255,200,0,.55); }
.tile.gold:not(.back) .face::after { content: '✨'; position: absolute; right: -6%; top: -8%; font-size: calc(var(--fs, 30px) * .32); line-height: 1; }
#board .tile.sp-joker:not(.back) { background: linear-gradient(160deg, #f3ecff 0%, #dccbff 60%, #c2a8ff 100%); }
.emo.sp { animation: spBob 1.6s ease-in-out infinite; display: inline-block; }
@keyframes spBob { 50% { transform: scale(1.1) rotate(-4deg); } }
/* a face-down tile that matches at once: it flips open while it flies */
.tile.flying.reveal .face { animation: faceReveal .26s ease-out; }
@keyframes faceReveal { from { transform: scaleX(0); } 60% { transform: scaleX(1.1); } }
/* ice, lock and key */
.tile .ob { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 2; }
.tile .ob::after { position: absolute; line-height: 1; font-size: calc(var(--fs, 30px) * .42); filter: drop-shadow(0 1px 1px rgba(0,0,0,.35)); }
.tile .ob[data-k^="ice"] { background: linear-gradient(155deg, rgba(225,245,255,.62) 0%, rgba(160,215,250,.5) 55%, rgba(120,190,240,.55) 100%); box-shadow: inset 0 0 0 3px rgba(140,205,255,.95), inset 0 0 14px 2px rgba(255,255,255,.9); }
.tile .ob[data-k="ice2"] { background: linear-gradient(155deg, rgba(225,245,255,.8) 0%, rgba(160,215,250,.72) 55%, rgba(110,180,235,.75) 100%); box-shadow: inset 0 0 0 5px rgba(120,195,255,1), inset 0 0 18px 4px rgba(255,255,255,.95); }
.tile .ob[data-k="ice"]::after { content: '❄️'; right: 2%; bottom: 3%; font-size: calc(var(--fs, 30px) * .5); }
.tile .ob[data-k="ice2"]::after { content: '❄️❄️'; right: 2%; bottom: 3%; font-size: calc(var(--fs, 30px) * .32); }
.tile .ob[data-k="lock"] { background: rgba(70,45,10,.26); box-shadow: inset 0 0 0 4px #9a6b1f; }
.tile .ob[data-k="lock"]::after { content: '🔒'; right: -4%; bottom: -3%; font-size: calc(var(--fs, 30px) * .62); filter: drop-shadow(0 2px 3px rgba(0,0,0,.5)); }
.tile .ob[data-k="key"] { box-shadow: inset 0 0 0 3px #e0a800, 0 0 10px 2px rgba(255,200,0,.6); }
.tile .ob[data-k="key"]::after { content: '🔑'; left: -4%; top: -6%; font-size: calc(var(--fs, 30px) * .46); }
/* A frozen key/lock keeps its badge at the top, clear of the snowflakes below. */
.tile .ob[data-marker]::before { position: absolute; left: -4%; top: -6%; line-height: 1; font-size: calc(var(--fs, 30px) * .46); filter: drop-shadow(0 1px 1px rgba(0,0,0,.35)); }
.tile .ob[data-marker="key"]::before { content: '🔑'; }
.tile .ob[data-marker="lock"]::before { content: '🔒'; }
/* the alarm clock: a badge with the moves left (red and pulsing for the last 5) */
#board .tile.clocked { box-shadow: 0 0 0 3px #ff7a2f, 0 0 12px 3px rgba(255,122,47,.6); }
#clockBadge { position: absolute; z-index: 1999999; display: flex; align-items: center; gap: 1px; padding: 1px 6px 1px 3px; border-radius: 99px; background: #fff3e6; border: 2px solid #ff7a2f; box-shadow: 0 2px 5px rgba(0,0,0,.4); line-height: 1.15; pointer-events: none; }
#clockBadge b { color: #b23c00; font-weight: 900; font-variant-numeric: tabular-nums; min-width: 1.2em; text-align: center; }
#clockBadge.urgent { background: #ff4d3d; border-color: #b51d10; animation: ckPulse .8s ease-in-out infinite; }
#clockBadge.urgent b { color: #fff; }
@keyframes ckPulse { 50% { transform: scale(1.18); } }
.tile .ob-open { position: absolute; right: -4%; bottom: -3%; z-index: 3; font-size: calc(var(--fs, 30px) * .62); line-height: 1; pointer-events: none; filter: drop-shadow(0 2px 3px rgba(0,0,0,.45)); animation: obOpen 1.1s ease forwards; }
@keyframes obOpen { 0% { transform: scale(1); } 25% { transform: scale(1.6) rotate(-14deg); } 55% { transform: scale(1.25); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }
.ob-crack { position: absolute; inset: 0; border-radius: inherit; pointer-events: none; z-index: 3; background: radial-gradient(circle, rgba(255,255,255,.95) 0%, rgba(180,225,255,.7) 40%, transparent 70%); animation: crack .55s ease-out forwards; }
@keyframes crack { from { opacity: 1; transform: scale(.6); } to { opacity: 0; transform: scale(1.5); } }
#board .tile.obhint { animation: nudgeShake 1.3s ease-in-out 1; box-shadow: 0 0 0 4px #7fd0ff, 0 0 16px 6px rgba(120,200,255,.85); }
/* An inset rim also marks the visible part of a neighbour under the pile. Keep its layer. */
.nt-ico { font-size: 72px; line-height: 1.1; animation: giftWiggle 1.4s ease-in-out infinite; display: inline-block; }
.clock-help { padding: 16px; }
#board .film-over { position: absolute; inset: 4px 8% auto; padding: 8px 12px; z-index: 3000000; background: var(--cream); border-radius: 22px; box-shadow: 0 8px 0 var(--cream2), 0 14px 30px rgba(0,0,0,.4); text-align: center; animation: pop .4s cubic-bezier(.3,1.5,.6,1); }   /* the clock's lose message in the intro film (board.js checkClock): at the top, so the clock tile that stayed shows */
#board .film-over h2 { margin: 0; } #board .film-over p { margin: 2px 0 0; }
.clock-help .nt-ico { font-size: 40px; }
.clock-help h2 { font-size: 26px; }
.clock-help p { font-size: 16px; line-height: 1.3; margin: 6px 0 10px; }
.clock-help .big-btn { padding: 11px 16px; margin-top: 8px; }
.clock-help .big-btn b { font-size: 24px; }
.clock-help .link-btn { margin-top: 2px; padding: 6px 16px; }
.tile-help { padding: 18px 16px; }
.tile-help h2 { font-size: 26px; line-height: 1.15; }
.tile-help p { font-size: 17px; line-height: 1.3; margin: 8px 0; }
.tile-help .big-btn b { font-size: 23px; }
.clock-help h2 { font-size: 24px; }
.clock-help p { font-size: 15px; line-height: 1.25; margin: 4px 0 6px; }
.clock-help .link-btn { padding-top: 4px; padding-bottom: 4px; }
.clock-help .nt-ico { display: none; }
/* the daily gift */
.gift-box { font-size: 86px; line-height: 1.1; cursor: pointer; display: inline-block; animation: giftWiggle 1.2s ease-in-out infinite; }
.gift-box.open { animation: pop .5s cubic-bezier(.3,1.6,.5,1); font-size: 64px; text-shadow: 0 4px 0 var(--gold-d), 0 0 22px rgba(255,200,0,.8); }
@keyframes giftWiggle { 0%, 60%, 100% { transform: rotate(0) scale(1); } 70% { transform: rotate(-10deg) scale(1.08); } 80% { transform: rotate(9deg) scale(1.08); } 90% { transform: rotate(-5deg); } }
/* a glowing tile is always free (nothing on top), so it is lifted above the whole pile (tiles use z-index layer*10000+...) */
@keyframes nudgeShake { 0%, 45%, 100% { transform: translate(0) rotate(0); } 5% { transform: translateX(-4px) rotate(-5deg); } 12% { transform: translateX(4px) rotate(5deg); } 19% { transform: translateX(-4px) rotate(-4deg); } 26% { transform: translateX(3px) rotate(3deg); } 33% { transform: translateX(-2px) rotate(-2deg); } 40% { transform: translateX(1px) rotate(1deg); } }
/* see-through: the tiles on top of a stuck tile, briefly */
#board .tile.xray { opacity: .22; }
#board .tile.lucky { animation: luckyGlow .55s ease-in-out infinite alternate; z-index: 1000001 !important; }
@keyframes luckyGlow { from { box-shadow: 0 0 0 3px #7ee36a, 0 0 10px 3px rgba(110,230,90,.6); } to { box-shadow: 0 0 0 5px #b7ff9e, 0 0 26px 10px rgba(140,255,110,.9); } }
.tile.lucky .face::before { content: '🍀'; position: absolute; left: -10%; top: -10%; font-size: calc(var(--fs, 30px) * .45); line-height: 1; }

/* ========== 12 themes: Zonnebloem prize ========== */
body.sunny .tile { background: var(--tile-face, linear-gradient(160deg, #fffef4 0%, #fff6d0 55%, #f9e39a 100%));
  box-shadow: calc(var(--d) * .5) calc(var(--d) * .6) 0 0 var(--tile-rim, #efd27a), var(--d) calc(var(--d) * 1.2) 0 0 var(--tile-lip, #5c9e34), calc(var(--d) * 1.1) calc(var(--d) * 1.5) calc(var(--d) * 1.2) 0 rgba(60,40,0,.35); }
body.sunny .tile.back { background: url(data:image/png;base64,) center / cover no-repeat; }
body.sunny #tray { background: var(--tray-bg, linear-gradient(#f3b73a, #c98317)); box-shadow: inset 0 3px 6px rgba(80,40,0,.45), 0 4px 0 var(--tray-lip, #8a5a10), 0 8px 14px rgba(0,0,0,.3); }
body.sunny #tray .slot { background: var(--tray-well, rgba(90,50,0,.28)); }
body.sunny .tmini { background: var(--tile-face, linear-gradient(160deg, #fffef4, #f9e39a)); box-shadow: 2px 2px 0 var(--tile-rim, #efd27a), 2px 4px 0 var(--tile-lip, #5c9e34); }
body.sunny #progressBar { background: linear-gradient(90deg, #fff27a, #ffb300); }
body.sunny #progressBar::before { background: #fff27a; }
#bg.sunfield::before { content: '🌻 🌻 🌻 🌻 🌻 🌻 🌻 🌻 🌻 🌻'; position: absolute; left: -30px; right: -30px; bottom: -14px; font-size: 64px; letter-spacing: -14px; white-space: nowrap; overflow: hidden; opacity: .85; }
#bg.sunfield::after { background: radial-gradient(circle at 50% 35%, transparent 55%, rgba(120,70,0,.18) 100%); }


/* ========== 13 screen sizes ========== */
@media (min-height: 760px) { .home-buttons { gap: 22px; } }
@media (max-height: 620px) { .logo { margin: 6px 0; } }
/* short screens (Safari with its bars): compact home screen, which also scrolls */
@media (max-height: 740px) {
  #home { padding-top: 10px; padding-bottom: 12px; }
  .logo { margin: 16px 0 8px; }
  .logo h1 { font-size: clamp(32px, 9.5vw, 44px); margin-top: 4px; }
  .home-buttons { gap: 12px; }
  .home-buttons .big-btn { padding-top: 12px; padding-bottom: 12px; }
  .row2 .mid-btn { padding: 10px 8px; }
  #nextUnlock { margin-top: 10px; }
}
@media (max-height: 600px) {
  .compact .goal { display: none; }
  .compact .stars { height: 48px; }
  .compact .stars .st { font-size: 38px; }
  .compact .stars .st:nth-child(2) { font-size: 48px; }
}

/* a message that came with a heart */
.heart-msg { font-size: 22px !important; font-weight: 800; line-height: 1.3; margin: 6px 0 10px !important; padding: 10px 14px; background: #fff3f7; border: 2px dashed #ff9fc0; border-radius: 16px; color: var(--ink); }
.heart-msg small { display: block; font-size: 15px; font-weight: 700; color: #c2306b; margin-top: 2px; }
#heartPop .heart-msg { margin: 8px 0 0 !important; }
.heart-big.sm { font-size: 60px; }
.msg-pick { display: grid; gap: 8px; margin: 6px 0 12px; }
.msg-pick .mp { font: inherit; font-size: 19px; font-weight: 800; padding: 12px 10px; border-radius: 16px; border: 3px solid #ff9fc0; background: #fff3f7; color: var(--ink); cursor: pointer; }
.msg-pick .mp:active { transform: scale(.97); }


.toolbar.gone { display: none; }
/* auto-finish: a big message over the pile, which plays itself now */
#autoBanner { position: absolute; left: 50%; top: 50%; z-index: 3000000; width: min(86%, 380px); transform: translate(-50%, -50%) scale(.85); opacity: 0; pointer-events: none;
  display: grid; justify-items: center; gap: 4px; text-align: center; padding: 18px 16px; border-radius: 24px; color: #fff;
  background: rgba(16, 70, 52, .86); box-shadow: 0 10px 30px rgba(0,0,0,.35), inset 0 0 0 3px rgba(255,215,90,.75); transition: opacity .35s, transform .35s cubic-bezier(.3,1.5,.6,1); }
#autoBanner.on { opacity: 1; transform: translate(-50%, -50%) scale(1); }
#autoBanner .ab-ico { font-size: 44px; line-height: 1; }
#autoBanner b { font-size: clamp(22px, 6.4vw, 30px); line-height: 1.15; text-wrap: balance; }
#autoBanner span:last-child { font-size: clamp(18px, 5vw, 23px); font-weight: 800; color: #ffe27a; }
@media (prefers-reduced-motion: reduce) { #autoBanner { transition: opacity .2s; transform: translate(-50%, -50%); } }

/* translated text (lang.js fx): takes the size of where it sits; fitTexts may make it smaller */
span.fx { font-size: inherit; }
/* Home fits the available safe area; decoration gives way before controls. */
#home .logo { min-height: 0; flex: 1 1 0; margin: 0; padding-bottom: 8px; overflow: hidden; }
#home .logo h1 { line-height: 1.05; margin-top: 6px; }
#home .greet { margin-top: 2px; }
/* the three hero tiles take whatever height the logo block has left under the title, greeting and tip, and the figure on
   each tile scales with the tile (--lt = tile width), so the tiles always show whole and the figure stays inside its tile */
#home .logo-tiles { --lt: clamp(26px, 8.4vh - 10px, 66px); height: calc(var(--lt) * 1.85); }
@supports (height: 1cqh) {
  #home .logo-tiles { flex: 1 1 0; min-height: 0; max-height: 122px; width: 100%; justify-content: center; container-type: size; height: auto; }
  #home .lt { --lt: min(66px, calc((100cqh - 6px) / 1.65)); }
}
@container (max-height: 40px) { #home .lt { display: none; } }
#home .lt { width: var(--lt); height: calc(var(--lt) * 1.3); padding: calc(var(--lt) * .06); border-radius: calc(var(--lt) * .18); }
#home .lt .emo { font-size: calc(var(--lt) * .8) !important; line-height: 1; overflow: hidden; }
#home .lt.t2 { margin-bottom: calc(var(--lt) * .27); }
@media (max-height: 520px) { #home .logo { padding-bottom: 0; } }   /* (the logo is squeezed to nothing there: its room under the tip must go too) */
#home .home-buttons { gap: clamp(8px, 1.7vh, 18px); }
#home #nextUnlock { margin-top: 0; }
#ranking .rrow { min-height: 76px; }
#ranking .rn { min-width: 0; overflow-wrap: anywhere; }
#ranking .rk { flex-shrink: 0; }
#ranking .header .chip { font-size: 16px; }
#wRanking { font-size: 15px; margin: 4px auto; padding: 3px 10px; }
@keyframes rankRise { from { transform: translateY(12px); background: #ffe58a; } to { transform: translateY(0); } }
.win-rank-rise { animation: rankRise .8s ease-out; }
@media (max-height: 740px), (max-width: 500px) and (max-height: 800px) {
  #home { padding: 8px 12px 12px; gap: 8px; }
  #home .logo h1 { font-size: clamp(26px, 8vw, 36px); }
  #home .greet { font-size: 17px; }
  #home .home-buttons .big-btn { padding: 10px 14px; gap: 12px; }
  #home .big-btn b { font-size: 26px; }
  #home .big-btn small { font-size: 16px; }
  #home .bb-icon { width: 44px; height: 44px; }
  #home .row2 { gap: 10px; }
  #home .row2 .mid-btn { padding: 9px 5px; font-size: 17px; }
  #home .goal { padding: 7px 10px; font-size: 15px; }
  #home .goal .g-ico { font-size: 28px; }
}
@media (orientation: landscape) and (max-height: 600px) {
  #home.active { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1.3fr); grid-template-rows: auto minmax(0, 1fr) auto; gap: 8px 18px; }
  #home .home-top { grid-column: 1; grid-row: 1; }
  #home .logo { grid-column: 1; grid-row: 2; }
  #home .home-buttons { grid-column: 2; grid-row: 1 / 4; align-self: center; }
  #home #nextUnlock { grid-column: 1; grid-row: 3; }
  #home .home-top .chip { padding: 5px 8px; font-size: 15px; }
  #home .home-top .icon-btn { width: 40px; height: 40px; }
  #home .logo h1 { font-size: 28px; }
  #home .home-buttons .big-btn { padding: 7px 10px; }
}

@media (max-height: 740px) {
  .compact .win-stats { flex-wrap: nowrap; gap: 5px; }
  .compact .win-stats div { padding: 4px 6px; gap: 4px; font-size: 13px; white-space: nowrap; }
  .compact .win-stats b { font-size: 18px; }
  .compact .win-stats .ws-streak, .compact .win-stats .ws-streak b { font-size: 14px; }
  .compact p.note { font-size: 14px; margin: 3px 0; }
  .compact .chase { font-size: 14px !important; }
  .compact .link-btn { padding-top: 3px; padding-bottom: 3px; }
}

#ranking { touch-action: pan-y pinch-zoom; }
#ranking .name-chip .ra { position: relative; }

/* Option A: a single family list in the original pink family-panel palette. */
#ranking .header { gap: 12px; padding: 20px 20px 12px; }
#ranking .header h2 { text-align: center; font-size: 29px; }
#ranking .header .icon-btn { width: 44px; height: 44px; font-size: 23px; }
#ranking #rankName { margin: 0; padding: 0; width: 44px; height: 44px; border-radius: 50%; display: grid; place-items: center; flex: none; }
#ranking #rankName .ra { width: 32px; height: 32px; font-size: 24px; }
#ranking > .scroll { padding: 12px 20px 28px; touch-action: pan-y pinch-zoom; }
#ranking .rk-tabs { position: relative; isolation: isolate; background: rgba(0,0,0,.2); padding: 5px; gap: 4px; border-radius: 18px; margin-bottom: 12px; }
#ranking .rk-tabs[data-mode="all"] { --rank-slide: 1; }
#ranking .rk-tabs::before {
  content: ''; position: absolute; z-index: -1; inset: 5px auto 5px 5px;
  width: calc((100% - 14px) / 2); border-radius: 13px; background: #ffe9f1; box-shadow: 0 3px 0 #e85d8f;
  transform: translateX(calc(var(--rank-slide, 0) * (100% + 4px)));
}
#ranking .rk-tabs button, #ranking .rk-tabs button.on { border-radius: 13px; background: none; box-shadow: none; color: #fff; padding: 11px 4px; font-size: 15px; min-width: 0; max-width: none; }
#ranking .rk-tabs[data-spot="week"] #rkWeek, #ranking .rk-tabs[data-spot="all"] #rkAll { color: #963d62; }
.rank-viewport { position: relative; overflow: hidden; }
.rank-viewport.rank-moving .rank-list { pointer-events: none; }
.rank-viewport #rankList { transform: translateX(var(--rank-x, 0px)); }
.rank-next { position: absolute; inset: 0 0 auto; transform: translateX(calc(var(--rank-x, 0px) + var(--rank-side, 0px))); }
.rank-next[hidden] { display: none; }
.rank-settling .rank-list, .rk-tabs.rank-settling::before { transition: transform 260ms cubic-bezier(.2,.7,.2,1); }
/* the page = tile + pink block; the block (not the page) is the pink box, so the tile slides with its page (redo rule 8) */
#ranking > .scroll { padding: 4px 12px 28px; }
#ranking > .scroll::-webkit-scrollbar { display: none; }
#ranking .rank-list { display: block; }
.rank-viewport { padding-bottom: 12px; }
#ranking .rk-tabs { margin-bottom: 12px; }
.week-tile { position: relative; height: 184px; box-sizing: border-box; margin: 0 0 14px; padding: 12px 14px; border-radius: 22px; color: #5a3a00;
  background: linear-gradient(160deg, #fff1a8, #ffd75e 45%, var(--gold)); box-shadow: 0 6px 0 var(--gold-d), 0 9px 16px rgba(0,0,0,.25); }
.week-tile .wt-top { display: flex; justify-content: space-between; align-items: center; font-size: 15px; font-weight: 900; }
.week-tile .wt-end { background: rgba(255,255,255,.55); border-radius: 999px; padding: 3px 10px; font-size: 14px; }
.week-tile .wgoal { display: flex; align-items: center; gap: 12px; margin: 6px 0 0; }
.week-tile .wgoal .next { font-size: 50px; line-height: 1; filter: drop-shadow(0 3px 3px rgba(0,0,0,.25)); }
.week-tile .wgoal .gt { flex: 1; min-width: 0; }
.week-tile .wgoal .gt b { display: block; font-size: 27px; font-weight: 900; line-height: 1; white-space: nowrap; }
.week-tile .wgoal .gt small { display: block; font-size: 18px; font-weight: 900; margin-top: 2px; white-space: nowrap; }
.week-tile .wgoal .rew { flex: none; padding: 8px 12px; border-radius: 16px; background: #fff; color: #5a3a00; font-size: 24px; font-weight: 900; box-shadow: 0 4px 0 var(--gold-d); }
.week-tile .track { position: relative; height: 14px; margin: 22px 6px 8px; border-radius: 9px; background: rgba(90,58,0,.18); }
.week-tile .track > i { display: block; height: 100%; border-radius: 9px; background: #fff; box-shadow: 0 0 0 2px rgba(255,255,255,.4); }
.week-tile .track .cupmark { position: absolute; bottom: 9px; transform: translateX(-50%); font-size: 20px; line-height: 1; }
.week-tile .track .cupmark.not { filter: grayscale(1); opacity: .45; }
.week-tile .now { font-size: 15px; font-weight: 800; opacity: .85; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
.week-tile .dots { display: flex; gap: 5px; margin: 12px 0 8px; }
.week-tile .dots i { flex: 1; height: 12px; border-radius: 6px; background: #fff; }
.week-tile .dots i.not { background: rgba(90,58,0,.18); }
.week-tile .foot { display: flex; align-items: center; justify-content: space-between; gap: 8px; }
.week-tile .foot .go { flex: none; padding: 5px 12px; border-radius: 14px; background: linear-gradient(#45d28a, var(--green)); color: #fff; font-size: 17px; font-weight: 900; box-shadow: 0 4px 0 var(--green-d); text-shadow: 0 1px 0 rgba(0,0,0,.18); }
.week-tile .medrew.plain { flex: none; display: grid; place-items: center; }
/* the PERFECT badge (Dennis 2026-11-26): one raised gold badge that shines, the same everywhere except the win screen, which keeps its PERFECT! word (Dennis 2026-11-26).
   Every size is in em: a place only sets font-size. .pf tilts and twinkles, .pf-in is the pill and holds the light sweep. */
.pf { position: relative; display: inline-block; flex: none; vertical-align: middle; line-height: 1; font-size: 17px; transform: rotate(-5deg); }
.pf-in { position: relative; display: block; overflow: hidden; isolation: isolate; padding: .3em .56em .24em; border-radius: 999px;
  font-weight: 900; letter-spacing: .03em; white-space: nowrap; color: #f06a00; border: max(1px, .08em) solid #ff9a1f;
  background: linear-gradient(165deg, #fffdf4 16%, #fff3c4 58%, #ffd75e); text-shadow: 0 .03em 0 #fffdf4, 0 .07em 0 #ffd23f;
  box-shadow: inset 0 0 0 max(1px, .05em) #fffdf4, inset 0 min(-2px, -.13em) 0 #ffd23f, 0 max(1.5px, .08em) 0 #e07000, 0 max(3px, .16em) 0 #c98a12, 0 .26em .42em rgba(124,68,0,.26); }   /* min px: small badges keep the raised look */
.pf-in::after { content: ''; position: absolute; z-index: 1; top: -60%; bottom: -60%; left: -60%; width: 32%; pointer-events: none; transform: skewX(-22deg);
  background: linear-gradient(90deg, transparent, rgba(255,255,255,.3) 23%, #fff 49%, rgba(255,255,255,.45) 60%, transparent); animation: pfShine 3s ease-in-out infinite; }
.pf::before, .pf::after { content: '✦'; position: absolute; z-index: 2; pointer-events: none; line-height: 1; color: #fff; opacity: 0;
  text-shadow: 0 0 .2em #ffd23f, 0 0 .45em #ffb000; animation: pfTwinkle 3s ease-in-out infinite; }
.pf::before { top: -.45em; right: -.22em; font-size: .74em; }
.pf::after { bottom: -.3em; left: -.05em; font-size: .46em; animation-delay: -.75s; }
@keyframes pfShine { 0%, 24% { left: -60%; } 60%, 100% { left: 140%; } }
@keyframes pfTwinkle { 0%, 50% { opacity: 0; transform: scale(.2) rotate(0); } 62% { opacity: 1; transform: scale(1) rotate(45deg); } 78%, 100% { opacity: 0; transform: scale(.2) rotate(90deg); } }
@media (prefers-reduced-motion: reduce) { .pf-in::after, .pf::before, .pf::after { animation: none; } .pf-in::after { left: -60%; } }
.pf-hero { font-size: clamp(30px, 10vw, 39px); }   /* the plaque */
.pf-nudge { font-size: 25px; }   /* the plaque's "Nog 3 levels voor jouw" line: big enough to read as the same badge */
/* the block: 412 px, rows scroll inside (390 px) and snap to whole rows */
.rank-block { box-sizing: border-box; height: 412px; padding: 8px 6px; border: 3px solid #ff7aa8; border-radius: 24px; background: linear-gradient(135deg, #ffe9f1, #ffd6e6); box-shadow: 0 5px 0 #e85d8f; overflow: hidden; }
.rank-block .rl-scroll { height: 390px; overflow-y: auto; display: grid; gap: 6px; align-content: start; overscroll-behavior: contain; scroll-snap-type: y mandatory; scroll-padding: 0; }
.rank-block .rl-scroll::-webkit-scrollbar { display: none; }
.rank-block .rl-scroll .rrow { scroll-snap-align: start; }
#ranking .rrow.tight { display: grid; min-height: 0; height: 60px; padding: 6px 6px; grid-template-columns: minmax(22px, max-content) 44px minmax(0, 1fr) auto 34px; grid-template-rows: auto; align-items: center; gap: 0 3px; position: relative; border: 0; border-radius: 16px; background: #fff5f8; box-shadow: 0 2px 0 #edb9cc; }
#ranking .rrow.tight.me { background: #fff; box-shadow: inset 0 0 0 2px #e85d8f, 0 2px 0 #e85d8f; }
#ranking .rrow.tight .rk { min-width: 0; font-size: 19px; text-align: center; color: #ad4870; white-space: nowrap; }
/* the avatar column leaves room for the widest frame ring (6 px, a box-shadow outside the avatar) so it never runs into the place or the name (Dennis 2026-11-27) */
#ranking .rrow.tight .ra { width: 32px; height: 32px; font-size: 23px; clip-path: none; justify-self: center; }
#ranking .rrow.tight .rn { min-width: 0; font-size: 16px; line-height: 1.15; overflow: hidden; white-space: nowrap; }
#ranking .rrow.tight .nm1 { display: flex; align-items: center; gap: 4px; min-width: 0; }
#ranking .rrow.tight .nm1 .nmt { overflow: hidden; text-overflow: ellipsis; }
#ranking .rrow.tight .nm1 i { font-style: normal; font-size: 12px; color: #a25b77; flex: none; }
#ranking .rrow.tight .pf { font-size: 9.5px; margin-left: 2px; }
#ranking .rrow.tight .rn small { display: block; margin-top: 3px; font-size: 13px; color: #9c6680; overflow: hidden; text-overflow: ellipsis; }
#ranking .rrow.tight .rn small .hs.seen { color: #318c47; font-size: inherit; margin: 0; display: inline; }
#ranking .rrow.tight .rp { display: block; text-align: right; font-size: 19px; line-height: 1.1; white-space: nowrap; font-variant-numeric: tabular-nums; }
#ranking .rrow.tight .rp.lvl { line-height: 1; }
#ranking .rrow.tight .rp.lvl small { display: block; margin: 0 0 1px; font-size: 11px; color: #9c6680; }
#ranking .rrow.tight .hb { width: 34px; display: grid; place-items: center; }
#ranking .rrow.tight .heart-btn { position: static; display: inline-grid; place-items: center; margin: 0; padding: 0; min-width: 34px; height: 34px; background: #ffe3a0; box-shadow: 0 2px 0 #dfb85c; font-size: 19px; }
#ranking .rrow.tight .heart-btn.sent { font-size: 13px; background: #e9f7df; box-shadow: none; }
@media (min-width: 600px) { #ranking .header, #ranking > .scroll { width: min(100%, 560px); align-self: center; } }

/* intro film (js/intro.js): a pop-up with a small board and tray of the game's own (core.js filmRoot) over the level */
.modal-box.intro-help { padding: 14px 12px 14px; animation: introIn .6s ease-out; }   /* it opens calmly: no bounce (the owner 2026-11-22) */
@keyframes introIn { from { opacity: 0; transform: scale(.96); } }
#introPanel h2 { margin: 0 0 8px; font-size: 26px; line-height: 1.15; }
.intro-stage { display: flex; flex-direction: column; align-items: center; padding-top: 8px; border-radius: 18px; overflow: hidden; box-shadow: inset 0 2px 6px rgba(0,0,0,.25); }
.intro-stage #boardWrap { flex: none; align-self: stretch; height: min(32vh, 250px); touch-action: auto; }
/* a film with the clock's number under its caption (two chips) gives the board less room on a short phone */
@media (max-height: 700px) { .intro-stage:has(.intro-count) #boardWrap { height: 24vh; } }
.intro-stage.intro-end { cursor: pointer; }
.intro-stage .intro-bar { flex: none; align-self: stretch; height: 30px; margin: 0 10px 4px; }   /* the game's top-bar texts (#gameMsg), above the film's tray */
/* the caption of a step, under the board (its row is always there, so nothing moves when it comes and goes) */
.intro-stage .intro-cap { max-width: calc(100% - 12px); margin: 2px 0 8px; min-height: calc(1.25em + 12px); font-size: 17px; line-height: 1.25; background: rgba(0,0,0,.42); opacity: 0; transition: opacity .18s; pointer-events: none; }
.intro-stage .intro-cap.on { opacity: 1; }
.intro-stage .intro-count { margin: -4px 0 8px; min-height: calc(1.25em + 12px); font-size: 17px; line-height: 1.25; background: rgba(0,0,0,.42); opacity: 0; transition: opacity .18s; pointer-events: none; }   /* the clock's number before → after a tap (INTRO_FILMS count) */
.intro-stage .intro-count.on { opacity: 1; }
#introPanel h2 { text-wrap: balance; }   /* (a long title on two even lines, no word alone) */
#introPanel .intro-line { font-size: 19px; line-height: 1.3; margin: 10px 0 4px; }
#introPanel .big-btn:disabled { opacity: .55; cursor: default; }
#introPanel .big-btn:disabled b { font-size: 21px; }

/* tall phones (Dennis's app: 392x785): the hero tiles grow first (up to 66 px), the height left after that is split above the
   tiles and below the bottom bar; the buttons follow the tip with a normal gap (the owner 2026-11-23, option C, "not perfect yet").
   The logo block is dissolved (display: contents) so its tiles are home's own flex item: a grown-out flex item lets the
   auto margins share the rest. */
@media (min-height: 741px) {
  #home { --hg: clamp(14px, 2.2vh, 24px); gap: 0; }
  #home .logo { display: contents; }
  #home .logo-tiles { --lt: initial; height: auto; flex: 1 1 0; min-height: 0; max-height: calc(122px + var(--hg)); padding-top: var(--hg); margin-top: auto; container-type: size; align-self: center; }
  #home .lt { --lt: min(66px, calc((100cqh - 6px) / 1.65)); }
  #home .logo h1, #home .greet { text-align: center; align-self: center; }
  #home .logo h1 { margin-top: 12px; }
  #home .home-tip { align-self: center; }
  #home .home-buttons, #home #nextUnlock { margin-top: var(--hg); }
  #home #nextUnlock { margin-bottom: auto; }
}

/* ---------- Winkel (shop) screen: tabs that swipe ---------- */
.shop-tabs { position: relative; isolation: isolate; display: flex; gap: 4px; margin: 0 16px 10px; padding: 5px; border-radius: 18px; background: rgba(0,0,0,.2); }
.shop-tabs::before { content: ''; position: absolute; z-index: -1; inset: 5px auto 5px 5px; width: calc((100% - 22px) / 4); border-radius: 13px;
  background: var(--cream); box-shadow: 0 3px 0 var(--cream2); transform: translateX(calc(var(--slide, 0) * (100% + 4px))); }
.shop-tabs button { flex: 1; min-width: 0; border-radius: 13px; background: none; color: #fff; padding: 10px 2px; font-size: 17px; font-weight: 900; }
.shop-tabs button.on { color: var(--ink); }
.shop-view { position: relative; flex: 1; overflow: hidden; touch-action: pan-y; }
.shop-view > .scroll { position: absolute; inset: 0; transform: translateX(var(--x, 0)); touch-action: pan-y; }
.shop-view .scroll::-webkit-scrollbar { display: none; }
.shop-settling > .scroll, .shop-tabs.shop-settling::before { transition: transform 260ms cubic-bezier(.2,.7,.2,1); }

/* ---- Winkel: Bord and Familie cards, price buttons, the buy popup ---- */
.price { display: inline-block; margin-top: 8px; padding: 4px 14px; border-radius: 999px; color: #fff; font-size: 18px; font-weight: 900;
  background: linear-gradient(#ffa865, var(--orange)); box-shadow: 0 3px 0 var(--orange-d); text-shadow: 0 1px 0 rgba(0,0,0,.18); }
.price.off { background: #d8ccb0; color: #7a6a48; text-shadow: none; box-shadow: 0 3px 0 #bfb08c; }
.th { display: flex; flex-direction: column; align-items: center; }
.th .nm { line-height: 1.1; }
.buy { display: flex; align-items: center; justify-content: center; gap: 6px; margin-top: auto; padding-top: 8px; }
.buy .price { margin: 0; }
.gift { display: inline-grid; place-items: center; width: 38px; height: 34px; border-radius: 12px; background: #ffe3a0; box-shadow: 0 3px 0 #dfb85c; font-size: 19px; }
.bgc.pay { align-items: flex-start; }   /* name on top, the price at the bottom: they never cover each other */
.bgc .buy { position: absolute; right: 10px; bottom: 10px; padding: 0; text-shadow: 0 1px 0 rgba(0,0,0,.18); }
.th .pv .mini.fin, .pvbig .mini.fin { box-shadow: 2px 3px 0 var(--lip), 3px 5px 0 rgba(0,0,0,.18); }
.trayprev { display: flex; gap: 4px; padding: 6px; border-radius: 12px; margin-bottom: 8px; box-shadow: inset 0 -3px 0 rgba(0,0,0,.25); }
.trayprev i { width: 28px; height: 36px; border-radius: 7px; background: rgba(0,0,0,.22); box-shadow: inset 0 2px 3px rgba(0,0,0,.3); }
.row-list { display: flex; flex-direction: column; gap: 14px; margin-bottom: 20px; }
.row-item { position: relative; display: flex; align-items: center; gap: 10px; width: 100%; background: var(--cream); border-radius: 20px; padding: 12px 12px;
  box-shadow: 0 6px 0 var(--cream2), 0 8px 12px rgba(0,0,0,.2); text-align: left; }
.row-item.on { box-shadow: 0 6px 0 var(--green-d), 0 0 0 5px var(--green), 0 8px 14px rgba(0,0,0,.25); }
.row-item.on::after { content: '✓'; position: absolute; top: -10px; right: -8px; width: 34px; height: 34px; border-radius: 50%; background: var(--green); color: #fff; display: grid; place-items: center; font-size: 22px; box-shadow: 0 2px 0 var(--green-d); }
.row-item .ico { width: 44px; height: 44px; flex: none; display: grid; place-items: center; font-size: 34px; }
.row-item .pbtn { width: 44px; height: 44px; border-radius: 16px; flex: none; display: grid; place-items: center; font-size: 22px; color: #fff;
  background: linear-gradient(#45d28a, var(--green)); box-shadow: 0 4px 0 var(--green-d); }
.row-item .tx { flex: 1; min-width: 0; }
.row-item .tx b { display: block; font-size: 18px; font-weight: 900; line-height: 1.2; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-item .tx small { display: block; font-size: 15px; font-weight: 800; color: var(--muted); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.row-item .buy { margin: 0; padding: 0; flex: none; }
.row-item .price { font-size: 16px; padding: 4px 10px; }
.row-item .gift { width: 34px; height: 32px; font-size: 17px; }
#shop .pv .cn, .modal-box .pvbig .cn { display: none; }   /* shop previews never show the corner numbers of the classic tiles */
.avf { width: 64px; height: 64px; border-radius: 50%; display: grid; place-items: center; font-size: 36px; background: #fff; margin: 4px 0 10px; }
.modal-box .pvbig { display: flex; justify-content: center; gap: 8px; margin: 10px 0 6px; }
.modal-box .pvbig .mini { width: 56px; height: 72px; border-radius: 10px; background: linear-gradient(#fffef8, #f1e6cb); box-shadow: 2px 4px 0 #d9caa0, 3px 6px 0 #1f7a5c; display: grid; place-items: center; padding: 2px; }
.modal-box .pvbig .mini svg { width: 100%; height: 100%; }
.modal-box .pvbig .mini .emo { font-size: 40px; }
.modal-box .pvbig .trayprev { margin: 0 auto; }
.modal-box .pvbig .avf { margin: 0; }
.modal-box .bgprev { height: 90px; border-radius: 18px; margin: 10px 0 6px; box-shadow: 0 4px 0 rgba(0,0,0,.2); }
.modal-box .bigico { font-size: 64px; line-height: 1; margin: 4px 0 6px; }
.big-btn.off { background: #d8ccb0; color: #7a6a48; text-shadow: none; box-shadow: 0 7px 0 #bfb08c, 0 10px 18px rgba(0,0,0,.2); }
.btn2 { display: block; width: 100%; margin-top: 14px; padding: 14px; border-radius: 22px; background: var(--cream); color: var(--ink); font-size: 22px; font-weight: 900;
  box-shadow: 0 5px 0 var(--cream2), 0 0 0 2px var(--cream2) inset; }
.btn-row { display: flex; gap: 10px; }
.btn-row .btn2 { flex: 1; }

/* gift picker */
.gift-list { margin: 8px 0 0; max-height: 46vh; overflow-y: auto; }
.gift-row { display: flex; align-items: center; gap: 10px; padding: 6px 4px; }
.gift-row + .gift-row { border-top: 2px dashed rgba(0,0,0,.12); }
.gift-row .ra { width: 44px; height: 44px; font-size: 28px; flex: none; }
.gift-row .gn { flex: 1; min-width: 0; text-align: left; font-size: 20px; font-weight: 900; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.gift-row .gbtn { flex: none; padding: 8px 18px; border-radius: 16px; background: var(--green); color: #fff; font-size: 20px; font-weight: 900; box-shadow: 0 4px 0 var(--green-d); }
.gift-row .gbtn:disabled { opacity: .5; }
